/// The agent repo a commit is made beside, and whether its commit is
/// made now, by `-s`, required: refused when it is left out, and when
/// it asks for a pair where there is none or a plain commit where
/// there is one.
fn commit_scope(
    scope: Option<&RepoScope>,
    agent: Option<PathBuf>,
    stage: &str,
) -> Result<Option<(PathBuf, bool)>, String> {
    match (scope, agent) {
        (None, _) => Err(format!(
            "cycle {stage}: -s is required, which repos: `b|both`, `w|work`, or `p|por`"
        )),
        (Some(RepoScope::Por), None) => Ok(None),
        (Some(RepoScope::Por), Some(_)) => Err(format!(
            "cycle {stage} -s p: this is a dual workspace, whose rung is a pair: -s b or -s w"
        )),
        (Some(RepoScope::Sides(_)), None) => Err(format!(
            "cycle {stage}: this is a plain repo, with no agent repo to pair with: -s p"
        )),
        (Some(RepoScope::Sides(sides)), Some(agent)) => Ok(Some((agent, sides.is_both()))),
    }
}

/// What `--close` lacks, every piece at once, so one refusal names all
/// of it: the shape, and with `--single-step` the body its one commit
/// needs. `None` when nothing is.
fn close_missing(a: &CycleArgs) -> Option<String> {
    let bodied = a.body.is_some() || a.default_body;
    let mut missing: Vec<&str> = Vec::new();
    if !a.single_step && !a.multi_step {
        missing.push(
            "the cycle's shape, --single-step, its one commit, or --multi-step, a ladder whose \
             closing is its own commit, which the branch's commits check and, with one commit, \
             the opening, it decides",
        );
        if !bodied {
            missing.push("with --single-step, --body or --default-body");
        }
    } else if a.single_step && !bodied {
        missing.push(
            "--body, the problem and solution of the one commit, which holds the work, or \
             --default-body for the pointer at the record",
        );
    }
    match missing.as_slice() {
        [] => None,
        [one] => Some(format!("cycle --close: it needs {one}")),
        many => Some(format!("cycle --close: it needs {}", many.join("; and "))),
    }
}

impl CycleArgs {
    /// The cycle a stage after `--open` works on.
    fn running(&self, work: PathBuf) -> Running {
        Running {
            work,
            bookmark: self.bookmark.clone(),
            dry_run: self.dry_run.value,
        }
    }

    /// `--open`'s params.
    fn open_params(&self, work: PathBuf, agent: Option<PathBuf>) -> Result<CycleParams, String> {
        if self.title.is_none() && self.bookmark.is_none() {
            return Err("cycle --open: --title or --bookmark names the bookmark".into());
        }
        let bookmark = crate::open::bookmark_name(self.bookmark.as_deref(), self.title.as_deref())?;
        if let Some(t) = &self.title {
            crate::commit::refuse_suffixed(t, "cycle --open --title")
                .map_err(|e| e.replacen("commit ", "", 1))?;
        }
        Ok(CycleParams::Open(OpenCycle {
            open: OpenParams {
                work,
                agent,
                bookmark,
                dry_run: self.dry_run.value,
            },
            record: match (&self.title, self.no_record) {
                (Some(t), false) => Some(t.trim().to_string()),
                _ => None,
            },
        }))
    }

    /// `--land`'s params, `None` when it is not asked for. With `alone`
    /// the title and body are the merge commit's, and after `--close`
    /// they are the closing's.
    fn land_params(
        &self,
        work: PathBuf,
        agent: Option<PathBuf>,
        alone: bool,
    ) -> Result<Option<LandCycle>, String> {
        let Some(dest) = &self.land else {
            return Ok(None);
        };
        if matches!(&self.scope, Some(RepoScope::Sides(s)) if !s.is_both()) {
            return Err(
                "cycle --land -s w: a work-only Land would publish trailers naming agent commits \
                 its agent half may not have published: -s b"
                    .into(),
            );
        }
        commit_scope(self.scope.as_ref(), agent.clone(), "--land")?;
        if alone && self.same_version {
            return Err("cycle --land: it takes no --same-version, a Land bumping nothing".into());
        }
        if alone && (self.title.is_some() || self.body.is_some()) && !self.merge {
            return Err(
                "cycle --land: a Land makes no commit of its own, so --title and --body are \
                 --merge's, the merge commit's"
                    .into(),
            );
        }
        let body = match (&self.body, alone) {
            (Some(b), true) => Some(crate::desc_helpers::read_body(b, "cycle --land")?),
            _ => None,
        };
        Ok(Some(LandCycle {
            running: self.running(work),
            agent,
            dest: dest.clone(),
            merge: self.merge,
            skip: self.skip,
            delete_intermediate: self.delete_intermediate_bookmarks,
            push: self.push,
            title: self.title.clone().filter(|_| alone),
            body,
        }))
    }

    /// A commit's params, `--commit`'s and `--close`'s alike.
    fn rung(
        &self,
        work: PathBuf,
        agent: Option<PathBuf>,
        stage: &str,
    ) -> Result<CommitRung, String> {
        let body = match &self.body {
            Some(b) => Some(crate::desc_helpers::read_body(
                b,
                &format!("cycle {stage}"),
            )?),
            None => None,
        };
        if self.title.as_deref().is_some_and(|t| t.trim().is_empty())
            || body.as_deref().is_some_and(|b| b.trim().is_empty())
        {
            return Err(format!(
                "cycle {stage}: a --title or --body given is not blank"
            ));
        }
        Ok(CommitRung {
            agent: commit_scope(self.scope.as_ref(), agent, stage)?,
            running: self.running(work),
            title: self.title.as_ref().map(|t| t.trim().to_string()),
            body,
            push: self.push,
            same_version: self.same_version,
        })
    }
}

impl TryFrom<&CycleArgs> for CycleParams {
    type Error = String;

    /// Resolve the workspace and the stage asked for.
    fn try_from(a: &CycleArgs) -> Result<Self, String> {
        let (work, agent) = resolve_repos(a.repo.as_deref())?;
        let only = |stage: &str, given: &[(&str, bool)]| match given.iter().find(|(_, g)| *g) {
            Some((flag, _)) => Err(format!("cycle {stage}: it takes no {flag}")),
            None => Ok(()),
        };
        let commits = [
            ("--same-version", a.same_version),
            ("-s", a.scope.is_some()),
            ("--push", a.push),
            ("--body", a.body.is_some()),
        ];
        if a.open {
            only("--open", &commits)?;
            a.open_params(work, agent)
        } else if a.ladder {
            only("--ladder", &commits)?;
            Ok(CycleParams::Ladder(a.running(work)))
        } else if a.status {
            only("--status", &commits)?;
            Ok(CycleParams::Status(a.running(work)))
        } else if let Some(heads) = &a.close {
            // A dead end's shape is wrong whatever else is given, so it is
            // said first.
            if a.dead_end && a.single_step {
                return Err(
                    "cycle --close --dead-end: a dead end closes the commits a cycle made with a \
                     closing commit of its own: --multi-step"
                        .into(),
                );
            }
            if let Some(missing) = close_missing(a) {
                return Err(missing);
            }
            let land = a.land_params(work.clone(), agent.clone(), false)?;
            let mut rung = a.rung(work, agent, "--close")?;
            // With a Land the push is the Land's, the destination's.
            rung.push = rung.push && land.is_none();
            Ok(CycleParams::Close(CloseCycle {
                rung,
                heads: heads.clone(),
                trapezoid: a.trapezoid.clone(),
                default_body: a.default_body,
                dead_end: a.dead_end,
                single_step: a.single_step,
                land,
            }))
        } else if let Some(land) = a.land_params(work.clone(), agent.clone(), true)? {
            Ok(CycleParams::Land(land))
        } else if a.commit {
            Ok(CycleParams::Commit(a.rung(work, agent, "--commit")?))
        } else {
            only(
                "--push",
                &[
                    ("--same-version", a.same_version),
                    ("--body", a.body.is_some()),
                    ("--title", a.title.is_some()),
                ],
            )?;
            if matches!(&a.scope, Some(RepoScope::Sides(s)) if !s.is_both()) {
                return Err(
                    "cycle --push -s w: the work half alone would publish trailers naming agent \
                     commits not yet published: -s b"
                        .into(),
                );
            }
            Ok(CycleParams::Push(PushCycle {
                agent: commit_scope(a.scope.as_ref(), agent, "--push")?.map(|(a, _)| a),
                running: a.running(work),
            }))
        }
    }
}

impl SubcommandRunner for CycleArgs {
    type Params = CycleParams;

    /// Delegate to the `TryFrom<&CycleArgs>` impl above.
    fn to_params(&self) -> Result<Self::Params, String> {
        CycleParams::try_from(self)
    }

    /// Run the `cycle` op.
    fn run(ctx: &mut Context, params: &Self::Params) -> Result<(), Box<dyn std::error::Error>> {
        cycle(ctx, params)
    }
}

/// Entry point: the stage asked for.
pub fn cycle(ctx: &mut Context, params: &CycleParams) -> Result<(), Box<dyn std::error::Error>> {
    debug!("cycle: enter {params:?}");
    match params {
        CycleParams::Open(o) => open(ctx, o),
        CycleParams::Ladder(r) => ladder(r),
        CycleParams::Commit(c) => commit_rung(ctx, c),
        CycleParams::Close(c) => close(ctx, c),
        CycleParams::Land(l) => land(ctx, l),
        CycleParams::Push(p) => push(ctx, p),
        CycleParams::Status(r) => {
            for line in status(r)? {
                info!("{line}");
            }
            Ok(())
        }
    }
}

/// The opening's body when none is given: `[opening] body` in the
/// config, its `{title}` the cycle title, else a sentence naming the
/// cycle, then the pointer to its record, [`with_pointer`].
fn opening_body(repo: &std::path::Path, cycle: &str) -> Result<String, Box<dyn std::error::Error>> {
    let configured = crate::config_md::load(repo)?
        .and_then(|cfg| crate::toml_simple::toml_get(&cfg.map, "opening.body").cloned());
    let body = match configured {
        Some(body) => body,
        None => "Opens the cycle \"{title}\".".to_string(),
    };
    Ok(with_pointer(&body.replace("{title}", cycle), cycle))
}

/// A bookend's body with the pointer to the cycle's record, its own
/// paragraph, two lines, the second the cycle's heading exactly as
/// written in the record, so a search finds it at any commit.
fn with_pointer(body: &str, cycle: &str) -> String {
    format!(
        "{}\n\nSee details in {}:\n### {cycle}",
        body.trim_end(),
        crate::commit::RECORD
    )
}

/// The params of the commit a stage makes, `vc-x1 commit`'s: the pair
/// or the plain repo, the description, and the cycle's bookmark the
/// one advanced.
fn commit_params(
    c: &CommitRung,
    title: String,
    body: String,
    bookmark: String,
) -> crate::commit::CommitParams {
    let target = match &c.agent {
        Some((agent, agent_now)) => crate::commit::Target::Pair {
            pair: crate::pair::Pair {
                work: c.running.work.clone(),
                agent: agent.clone(),
            },
            agent_now: *agent_now,
        },
        None => crate::commit::Target::Por(c.running.work.clone()),
    };
    crate::commit::CommitParams {
        target,
        title: Some(title),
        body: Some(body),
        advance: crate::commit::Advance::Named(bookmark),
        push: c.push,
        no_url_trailer: false,
        dry_run: c.running.dry_run,
        rev: None,
        covers: None,
        allow_empty: false,
        same_version: c.same_version,
        land_follows: false,
    }
}

/// `--commit`: commit the working copies as a rung of the cycle in
/// progress. The cycle's first commit is its opening, titled and
/// bodied by default, and any other is a work rung, whose title is a
/// rung heading not yet committed. The ladder is rewritten first, the
/// rung done, so the commit carries it, and the cycle's bookmark is
/// the one advanced. Every check is made before the ladder is written.
fn commit_rung(ctx: &mut Context, c: &CommitRung) -> Result<(), Box<dyn std::error::Error>> {
    let stage = "--commit";
    let r = &c.running;
    let work = r.work.as_path();
    let bookmark = cycle_bookmark(r, stage)?;
    let commits = branch_titles(work, &bookmark)?;
    let path = work.join(crate::commit::RECORD);
    let todo = std::fs::read_to_string(&path)
        .map_err(|e| format!("cycle {stage}: {}: {e}", path.display()))?;
    let cycle = record::cycle_title(&todo).map_err(|e| format!("cycle {stage}: {e}"))?;
    let rungs = record::rung_titles(&todo).map_err(|e| format!("cycle {stage}: {e}"))?;
    let (opening, closing) = (format!("{cycle} opening"), format!("{cycle} closing"));
    let first = commits.is_empty();
    let title = match (&c.title, first) {
        (None, true) => opening.clone(),
        (Some(t), true) if *t == opening => opening.clone(),
        (Some(t), true) => {
            return Err(format!(
                "cycle {stage}: the cycle has no commit yet, so this one is its opening, \
                 '{opening}', and not '{t}': leave --title out"
            )
            .into());
        }
        (None, false) => {
            return Err(format!(
                "cycle {stage}: the opening is committed, so this is a work rung, which gives \
                 --title, a heading under `#### Rungs`, and --body"
            )
            .into());
        }
        (Some(t), false) => t.clone(),
    };
    if title == closing {
        return Err(format!(
            "cycle {stage}: '{title}' is the cycle's closing, which `cycle --close` makes"
        )
        .into());
    }
    if commits.contains(&title) {
        return Err(format!(
            "cycle {stage}: the rung '{title}' is committed already: `vc-x1 squash` continues it"
        )
        .into());
    }
    if !rungs.contains(&title) {
        return Err(format!(
            "cycle {stage}: '{title}' is no rung of the cycle, a `##### ` heading under `#### \
             Rungs` in {}: write its heading first",
            crate::commit::RECORD
        )
        .into());
    }
    let body = match (&c.body, first) {
        (Some(b), _) => b.clone(),
        (None, true) => opening_body(work, &cycle)?,
        (None, false) => {
            return Err(format!(
                "cycle {stage}: a work rung gives --body, its problem and solution"
            )
            .into());
        }
    };
    crate::pair::refuse_conflicts(work, "cycle --commit", "work")?;
    if jj::is_empty(work, "@")? {
        return Err(format!(
            "cycle {stage}: nothing to commit, the work repo's @ is empty ('{}')",
            work.display()
        )
        .into());
    }
    crate::commit::check_version(work, "@", c.same_version, "cycle --commit")?;
    let mut with = commits.clone();
    with.push(title.clone());
    let plan = record::plan_ladder(work, &with).map_err(|e| format!("cycle {stage}: {e}"))?;
    for finding in &plan.ladder.findings {
        warn!("cycle {stage}: {finding}");
    }
    info!(
        "cycle {stage}: {} '{title}' on '{bookmark}'",
        if first { "the opening" } else { "the rung" }
    );
    let params = commit_params(c, title, body, bookmark);
    let Some(edit) = plan.edit.as_ref().filter(|_| !r.dry_run) else {
        if plan.edit.is_some() {
            info!(
                "cycle {stage}: [dry-run] rewrite the ladder in {}, the rung done",
                record::LADDER_FILE
            );
        }
        return crate::commit::commit(ctx, &params);
    };
    // The ladder is written before the commit, which carries it, and
    // put back as it was when the commit is not made.
    let old = std::fs::read_to_string(&edit.path)?;
    std::fs::write(&edit.path, &edit.text)?;
    info!(
        "cycle {stage}: the ladder in {} is rewritten, the rung done",
        record::LADDER_FILE
    );
    crate::commit::commit(ctx, &params).inspect_err(|_| {
        if let Err(e) = std::fs::write(&edit.path, &old) {
            warn!(
                "cycle {stage}: the ladder in {} was not put back: {e}",
                edit.path.display()
            );
        }
    })
}

/// The revset of the cycle's branch: the commits `bookmark` reaches,
/// and those above it up to the work `@-`, a commit made by hand not
/// having advanced it, that no other local bookmark reaches.
fn branch_revset(bookmark: &str) -> String {
    let own = format!("bookmarks(exact:\"{bookmark}\")");
    format!("((::({own}) | ({own})::@-) ~ ::(bookmarks() ~ {own}))")
}

/// The titles of the commits on the cycle's branch in `repo`, oldest
/// first: the commits `bookmark` reaches, and those above it up to the
/// work `@-`, that no other local bookmark reaches, so no destination
/// is named or stored, less a working copy not yet described.
pub(crate) fn branch_titles(
    repo: &std::path::Path,
    bookmark: &str,
) -> Result<Vec<String>, Box<dyn std::error::Error>> {
    let mut titles = Vec::new();
    for cid in jj::cids_of(repo, &branch_revset(bookmark))? {
        let desc = jj::desc_of(repo, &cid)?;
        let title = desc.lines().next().unwrap_or_default().trim_end();
        if !title.is_empty() {
            titles.push(title.to_string());
        }
    }
    Ok(titles)
}

/// The bookmark of the cycle in progress in `r`'s workspace: the one
/// named, else the slug of the title in `TODO.md`, refused when the
/// work repo has no such bookmark.
pub(crate) fn cycle_bookmark(
    r: &Running,
    stage: &str,
) -> Result<String, Box<dyn std::error::Error>> {
    let name = match &r.bookmark {
        Some(name) => name.clone(),
        None => {
            let path = r.work.join(crate::commit::RECORD);
            let todo = std::fs::read_to_string(&path)
                .map_err(|e| format!("cycle {stage}: {}: {e}", path.display()))?;
            let title = record::cycle_title(&todo).map_err(|e| format!("cycle {stage}: {e}"))?;
            crate::check::anchors::anchor_slug(&title)
        }
    };
    if !jj::local_bookmark_exists(&r.work, &name)? {
        return Err(format!(
            "cycle {stage}: the cycle's bookmark '{name}' is not in {}: name it, --bookmark <NAME>",
            r.work.display()
        )
        .into());
    }
    Ok(name)
}

/// `--ladder`: make the ladder from the rung headings and the cycle's
/// commits, and write it, or with a dry run print it.
fn ladder(r: &Running) -> Result<(), Box<dyn std::error::Error>> {
    let bookmark = cycle_bookmark(r, "--ladder")?;
    let commits = branch_titles(&r.work, &bookmark)?;
    let plan =
        record::plan_ladder(&r.work, &commits).map_err(|e| format!("cycle --ladder: {e}"))?;
    for line in &plan.ladder.lines {
        info!("{line}");
    }
    for finding in &plan.ladder.findings {
        warn!("cycle --ladder: {finding}");
    }
    match (&plan.edit, r.dry_run) {
        (None, _) => info!(
            "cycle --ladder: the ladder in {} is as the rungs make it",
            record::LADDER_FILE
        ),
        (Some(_), true) => info!(
            "cycle --ladder: [dry-run] write the ladder into {}",
            record::LADDER_FILE
        ),
        (Some(edit), false) => {
            std::fs::write(&edit.path, &edit.text)
                .map_err(|e| format!("cycle --ladder: {}: {e}", edit.path.display()))?;
            info!(
                "cycle --ladder: the ladder is written into {}",
                record::LADDER_FILE
            );
        }
    }
    Ok(())
}

/// `--open`: plan the record, make the bookmark, then write the
/// record, so a record that cannot be written makes no bookmark, and a
/// name in use writes no record.
/// What is wrong with `title` as a cycle title, a line each: one that
/// is no Conventional Commit, `<type>: <desc>` or `<type>(<scope>):
/// <desc>`, and one over 50 characters, the bookends then longer still.
/// Empty when it is right.
pub(crate) fn title_problems(title: &str) -> Vec<String> {
    let mut problems = Vec::new();
    let conventional = title.split_once(": ").is_some_and(|(kind, desc)| {
        let kind = kind.strip_suffix('!').unwrap_or(kind);
        let (kind, scope) = match kind.split_once('(') {
            Some((k, rest)) => (k, rest.strip_suffix(')')),
            None => (kind, Some("x")),
        };
        !kind.is_empty()
            && kind.chars().all(|c| c.is_ascii_lowercase())
            && scope.is_some_and(|s| !s.is_empty())
            && !desc.trim().is_empty()
    });
    if !conventional {
        problems.push(format!(
            "'{title}' is no Conventional Commit, `<type>: <desc>`, `feat: x` for one"
        ));
    }
    let n = title.chars().count();
    if n > 50 {
        problems.push(format!(
            "'{title}' is {n} characters, over the 50 a title keeps to, its bookends longer still"
        ));
    }
    problems
}

fn open(ctx: &mut Context, o: &OpenCycle) -> Result<(), Box<dyn std::error::Error>> {
    let dry_run = o.open.dry_run;
    if let Some(title) = &o.record {
        for problem in title_problems(title) {
            warn!("cycle --open: {problem}, and every commit of the cycle carries it");
        }
    }
    let plan = match &o.record {
        Some(title) => {
            record::plan_open(&o.open.work, title).map_err(|e| format!("cycle --open: {e}"))?
        }
        None => {
            info!("cycle --open: no record is written, the bookmark being made alone");
            record::OpenRecord::default()
        }
    };
    crate::open::open(ctx, &o.open)?;
    let tag = if dry_run {
        "cycle --open: [dry-run]"
    } else {
        "cycle --open:"
    };
    for line in &plan.did {
        info!("{tag} {line}");
    }
    if dry_run {
        return Ok(());
    }
    for edit in &plan.edits {
        std::fs::write(&edit.path, &edit.text)
            .map_err(|e| format!("cycle --open: {}: {e}", edit.path.display()))?;
    }
    if !plan.edits.is_empty() {
        info!(
            "cycle --open: the record is written and nothing is committed: plan the cycle in it, \
             and bump the version"
        );
    }
    Ok(())
}

/// A closing's body when none is given: `[closing] body` in the
/// config, its `{title}` the cycle title, else a sentence naming the
/// cycle, then the pointer to its record, [`with_pointer`].
fn closing_body(repo: &std::path::Path, cycle: &str) -> Result<String, Box<dyn std::error::Error>> {
    let configured = crate::config_md::load(repo)?
        .and_then(|cfg| crate::toml_simple::toml_get(&cfg.map, "closing.body").cloned());
    let body = match configured {
        Some(body) => body,

                .map_err(|e| e.to_string())?;
            match repos.as_slice() {
                [repo] => Ok((repo.clone(), None)),
                other => Err(format!("cycle: expected one repo, got {}", other.len())),
            }
        }
    }
}

/// The agent repo a commit is made beside, and whether its commit is
/// made now, by `-s`, required: refused when it is left out, and when
/// it asks for a pair where there is none or a plain commit where
/// there is one.
fn commit_scope(
    scope: Option<&RepoScope>,
    agent: Option<PathBuf>,
    stage: &str,
) -> Result<Option<(PathBuf, bool)>, String> {
    match (scope, agent) {
        (None, _) => Err(format!(
            "cycle {stage}: -s is required, which repos: `b|both`, `w|work`, or `p|por`"
        )),
        (Some(RepoScope::Por), None) => Ok(None),
        (Some(RepoScope::Por), Some(_)) => Err(format!(
            "cycle {stage} -s p: this is a dual workspace, whose rung is a pair: -s b or -s w"
        )),
        (Some(RepoScope::Sides(_)), None) => Err(format!(
            "cycle {stage}: this is a plain repo, with no agent repo to pair with: -s p"
        )),
        (Some(RepoScope::Sides(sides)), Some(agent)) => Ok(Some((agent, sides.is_both()))),
    }
}

/// What `--close` lacks, every piece at once, so one refusal names all
/// of it: the shape, and with `--single-step` the body its one commit
/// needs. `None` when nothing is.
fn close_missing(a: &CycleArgs) -> Option<String> {
    let bodied = a.body.is_some() || a.default_body;
    let mut missing: Vec<&str> = Vec::new();
    if !a.single_step && !a.multi_step {
        missing.push(
            "the cycle's shape, --single-step, its one commit, or --multi-step, a ladder whose \
             closing is its own commit, which the branch's commits check and, with one commit, \
             the opening, it decides",
        );
        if !bodied {
            missing.push("with --single-step, --body or --default-body");
        }
    } else if a.single_step && !bodied {
        missing.push(
            "--body, the problem and solution of the one commit, which holds the work, or \
             --default-body for the pointer at the record",
        );
    }
    match missing.as_slice() {
        [] => None,
        [one] => Some(format!("cycle --close: it needs {one}")),
        many => Some(format!("cycle --close: it needs {}", many.join("; and "))),
    }
}

impl CycleArgs {
    /// The cycle a stage after `--open` works on.
    fn running(&self, work: PathBuf) -> Running {
        Running {
            work,
            bookmark: self.bookmark.clone(),
            dry_run: self.dry_run.value,
        }
    }

    /// `--open`'s params.
    fn open_params(&self, work: PathBuf, agent: Option<PathBuf>) -> Result<CycleParams, String> {
        if self.title.is_none() && self.bookmark.is_none() {
            return Err("cycle --open: --title or --bookmark names the bookmark".into());
        }
        let bookmark = crate::open::bookmark_name(self.bookmark.as_deref(), self.title.as_deref())?;
        if let Some(t) = &self.title {
            crate::commit::refuse_suffixed(t, "cycle --open --title")
                .map_err(|e| e.replacen("commit ", "", 1))?;
        }
        Ok(CycleParams::Open(OpenCycle {
            open: OpenParams {
                work,
                agent,
                bookmark,
                dry_run: self.dry_run.value,
            },
            record: match (&self.title, self.no_record) {
                (Some(t), false) => Some(t.trim().to_string()),
                _ => None,
            },
        }))
    }

    /// `--land`'s params, `None` when it is not asked for. With `alone`
    /// the title and body are the merge commit's, and after `--close`
    /// they are the closing's.
    fn land_params(
        &self,
        work: PathBuf,
        agent: Option<PathBuf>,
        alone: bool,
    ) -> Result<Option<LandCycle>, String> {
        let Some(dest) = &self.land else {
            return Ok(None);
        };
        if matches!(&self.scope, Some(RepoScope::Sides(s)) if !s.is_both()) {
            return Err(
                "cycle --land -s w: a work-only Land would publish trailers naming agent commits \
                 its agent half may not have published: -s b"
                    .into(),
            );
        }
        commit_scope(self.scope.as_ref(), agent.clone(), "--land")?;
        if alone && self.same_version {
            return Err("cycle --land: it takes no --same-version, a Land bumping nothing".into());
        }
        if alone && (self.title.is_some() || self.body.is_some()) && !self.merge {
            return Err(
                "cycle --land: a Land makes no commit of its own, so --title and --body are \
                 --merge's, the merge commit's"
                    .into(),
            );
        }
        let body = match (&self.body, alone) {
            (Some(b), true) => Some(crate::desc_helpers::read_body(b, "cycle --land")?),
            _ => None,
        };
        Ok(Some(LandCycle {
            running: self.running(work),
            agent,
            dest: dest.clone(),
            merge: self.merge,
            skip: self.skip,
            delete_intermediate: self.delete_intermediate_bookmarks,
            push: self.push,
            title: self.title.clone().filter(|_| alone),
            body,
        }))
    }

    /// A commit's params, `--commit`'s and `--close`'s alike.
    fn rung(
        &self,
        work: PathBuf,
        agent: Option<PathBuf>,
        stage: &str,
    ) -> Result<CommitRung, String> {
        let body = match &self.body {
            Some(b) => Some(crate::desc_helpers::read_body(
                b,
                &format!("cycle {stage}"),
            )?),
            None => None,
        };
        if self.title.as_deref().is_some_and(|t| t.trim().is_empty())
            || body.as_deref().is_some_and(|b| b.trim().is_empty())
        {
            return Err(format!(
                "cycle {stage}: a --title or --body given is not blank"
            ));
        }
        Ok(CommitRung {
            agent: commit_scope(self.scope.as_ref(), agent, stage)?,
            running: self.running(work),
            title: self.title.as_ref().map(|t| t.trim().to_string()),
            body,
            push: self.push,
            same_version: self.same_version,
        })
    }
}

impl TryFrom<&CycleArgs> for CycleParams {
    type Error = String;

    /// Resolve the workspace and the stage asked for.
    fn try_from(a: &CycleArgs) -> Result<Self, String> {
        let (work, agent) = resolve_repos(a.repo.as_deref())?;
        let only = |stage: &str, given: &[(&str, bool)]| match given.iter().find(|(_, g)| *g) {
            Some((flag, _)) => Err(format!("cycle {stage}: it takes no {flag}")),
            None => Ok(()),
        };
        let commits = [
            ("--same-version", a.same_version),
            ("-s", a.scope.is_some()),
            ("--push", a.push),
            ("--body", a.body.is_some()),
        ];
        if a.open {
            only("--open", &commits)?;
            a.open_params(work, agent)
        } else if a.ladder {
            only("--ladder", &commits)?;
            Ok(CycleParams::Ladder(a.running(work)))
        } else if a.status {
            only("--status", &commits)?;
            Ok(CycleParams::Status(a.running(work)))
        } else if let Some(heads) = &a.close {
            // A dead end's shape is wrong whatever else is given, so it is
            // said first.
            if a.dead_end && a.single_step {
                return Err(
                    "cycle --close --dead-end: a dead end closes the commits a cycle made with a \
                     closing commit of its own: --multi-step"
                        .into(),
                );
            }
            if let Some(missing) = close_missing(a) {
                return Err(missing);
            }
            let land = a.land_params(work.clone(), agent.clone(), false)?;
            let mut rung = a.rung(work, agent, "--close")?;
            // With a Land the push is the Land's, the destination's.
            rung.push = rung.push && land.is_none();
            Ok(CycleParams::Close(CloseCycle {
                rung,
                heads: heads.clone(),
                trapezoid: a.trapezoid.clone(),
                default_body: a.default_body,
                dead_end: a.dead_end,
                single_step: a.single_step,
                land,
            }))
        } else if let Some(land) = a.land_params(work.clone(), agent.clone(), true)? {
            Ok(CycleParams::Land(land))
        } else if a.commit {
            Ok(CycleParams::Commit(a.rung(work, agent, "--commit")?))
        } else {
            only(
                "--push",
                &[
                    ("--same-version", a.same_version),
                    ("--body", a.body.is_some()),
                    ("--title", a.title.is_some()),
                ],
            )?;
            if matches!(&a.scope, Some(RepoScope::Sides(s)) if !s.is_both()) {
                return Err(
                    "cycle --push -s w: the work half alone would publish trailers naming agent \
                     commits not yet published: -s b"
                        .into(),
                );
            }
            Ok(CycleParams::Push(PushCycle {
                agent: commit_scope(a.scope.as_ref(), agent, "--push")?.map(|(a, _)| a),
                running: a.running(work),
            }))
        }
    }
}

impl SubcommandRunner for CycleArgs {
    type Params = CycleParams;

    /// Delegate to the `TryFrom<&CycleArgs>` impl above.
    fn to_params(&self) -> Result<Self::Params, String> {
        CycleParams::try_from(self)
    }

    /// Run the `cycle` op.
    fn run(ctx: &mut Context, params: &Self::Params) -> Result<(), Box<dyn std::error::Error>> {
        cycle(ctx, params)
    }
}

/// Entry point: the stage asked for.
pub fn cycle(ctx: &mut Context, params: &CycleParams) -> Result<(), Box<dyn std::error::Error>> {
    debug!("cycle: enter {params:?}");
    match params {
        CycleParams::Open(o) => open(ctx, o),
        CycleParams::Ladder(r) => ladder(r),
        CycleParams::Commit(c) => commit_rung(ctx, c),
        CycleParams::Close(c) => close(ctx, c),
        CycleParams::Land(l) => land(ctx, l),
        CycleParams::Push(p) => push(ctx, p),
        CycleParams::Status(r) => {
            for line in status(r)? {
                info!("{line}");
            }
            Ok(())
        }
    }
}

/// The opening's body when none is given: `[opening] body` in the
/// config, its `{title}` the cycle title, else a sentence naming the
/// cycle, then the pointer to its record, [`with_pointer`].
fn opening_body(repo: &std::path::Path, cycle: &str) -> Result<String, Box<dyn std::error::Error>> {
    let configured = crate::config_md::load(repo)?
        .and_then(|cfg| crate::toml_simple::toml_get(&cfg.map, "opening.body").cloned());
    let body = match configured {
        Some(body) => body,
        None => "Opens the cycle \"{title}\".".to_string(),
    };
    Ok(with_pointer(&body.replace("{title}", cycle), cycle))
}

/// A bookend's body with the pointer to the cycle's record, its own
/// paragraph, two lines, the second the cycle's heading exactly as
/// written in the record, so a search finds it at any commit.
fn with_pointer(body: &str, cycle: &str) -> String {
    format!(
        "{}\n\nSee details in {}:\n### {cycle}",
        body.trim_end(),
        crate::commit::RECORD
    )
}

/// The params of the commit a stage makes, `vc-x1 commit`'s: the pair
/// or the plain repo, the description, and the cycle's bookmark the
/// one advanced.
fn commit_params(
    c: &CommitRung,
    title: String,
    body: String,
    bookmark: String,
) -> crate::commit::CommitParams {
    let target = match &c.agent {
        Some((agent, agent_now)) => crate::commit::Target::Pair {
            pair: crate::pair::Pair {
                work: c.running.work.clone(),
                agent: agent.clone(),
            },
            agent_now: *agent_now,
        },
        None => crate::commit::Target::Por(c.running.work.clone()),
    };
    crate::commit::CommitParams {
        target,
        title: Some(title),
        body: Some(body),
        advance: crate::commit::Advance::Named(bookmark),
        push: c.push,
        no_url_trailer: false,
        dry_run: c.running.dry_run,
        rev: None,
        covers: None,
        allow_empty: false,
        same_version: c.same_version,
        land_follows: false,
    }
}

/// `--commit`: commit the working copies as a rung of the cycle in
/// progress. The cycle's first commit is its opening, titled and
/// bodied by default, and any other is a work rung, whose title is a
/// rung heading not yet committed. The ladder is rewritten first, the
/// rung done, so the commit carries it, and the cycle's bookmark is
/// the one advanced. Every check is made before the ladder is written.
fn commit_rung(ctx: &mut Context, c: &CommitRung) -> Result<(), Box<dyn std::error::Error>> {
    let stage = "--commit";
    let r = &c.running;
    let work = r.work.as_path();
    let bookmark = cycle_bookmark(r, stage)?;
    let commits = branch_titles(work, &bookmark)?;
    let path = work.join(crate::commit::RECORD);
    let todo = std::fs::read_to_string(&path)
        .map_err(|e| format!("cycle {stage}: {}: {e}", path.display()))?;
    let cycle = record::cycle_title(&todo).map_err(|e| format!("cycle {stage}: {e}"))?;
    let rungs = record::rung_titles(&todo).map_err(|e| format!("cycle {stage}: {e}"))?;
    let (opening, closing) = (format!("{cycle} opening"), format!("{cycle} closing"));
    let first = commits.is_empty();
    let title = match (&c.title, first) {
        (None, true) => opening.clone(),
        (Some(t), true) if *t == opening => opening.clone(),
        (Some(t), true) => {
            return Err(format!(
                "cycle {stage}: the cycle has no commit yet, so this one is its opening, \
                 '{opening}', and not '{t}': leave --title out"
            )
            .into());
        }
        (None, false) => {
            return Err(format!(
                "cycle {stage}: the opening is committed, so this is a work rung, which gives \
                 --title, a heading under `#### Rungs`, and --body"
            )
            .into());
        }
        (Some(t), false) => t.clone(),
    };
    if title == closing {
        return Err(format!(
            "cycle {stage}: '{title}' is the cycle's closing, which `cycle --close` makes"
        )
        .into());
    }
    if commits.contains(&title) {
        return Err(format!(
            "cycle {stage}: the rung '{title}' is committed already: `vc-x1 squash` continues it"
        )
        .into());
    }
    if !rungs.contains(&title) {
        return Err(format!(
            "cycle {stage}: '{title}' is no rung of the cycle, a `##### ` heading under `#### \
             Rungs` in {}: write its heading first",
            crate::commit::RECORD
        )
        .into());
    }
    let body = match (&c.body, first) {
        (Some(b), _) => b.clone(),
        (None, true) => opening_body(work, &cycle)?,
        (None, false) => {
            return Err(format!(
                "cycle {stage}: a work rung gives --body, its problem and solution"
            )
            .into());
        }
    };
    crate::pair::refuse_conflicts(work, "cycle --commit", "work")?;
    if jj::is_empty(work, "@")? {
        return Err(format!(
            "cycle {stage}: nothing to commit, the work repo's @ is empty ('{}')",
            work.display()
        )
        .into());
    }
    crate::commit::check_version(work, "@", c.same_version, "cycle --commit")?;
    let mut with = commits.clone();
    with.push(title.clone());
    let plan = record::plan_ladder(work, &with).map_err(|e| format!("cycle {stage}: {e}"))?;
    for finding in &plan.ladder.findings {
        warn!("cycle {stage}: {finding}");
    }
    info!(
        "cycle {stage}: {} '{title}' on '{bookmark}'",
        if first { "the opening" } else { "the rung" }
    );
    let params = commit_params(c, title, body, bookmark);
    let Some(edit) = plan.edit.as_ref().filter(|_| !r.dry_run) else {
        if plan.edit.is_some() {
            info!(
                "cycle {stage}: [dry-run] rewrite the ladder in {}, the rung done",
                record::LADDER_FILE
            );
        }
        return crate::commit::commit(ctx, &params);
    };
    // The ladder is written before the commit, which carries it, and
    // put back as it was when the commit is not made.
    let old = std::fs::read_to_string(&edit.path)?;
    std::fs::write(&edit.path, &edit.text)?;
    info!(
        "cycle {stage}: the ladder in {} is rewritten, the rung done",
        record::LADDER_FILE
    );
    crate::commit::commit(ctx, &params).inspect_err(|_| {
        if let Err(e) = std::fs::write(&edit.path, &old) {
            warn!(
                "cycle {stage}: the ladder in {} was not put back: {e}",
                edit.path.display()
            );
        }
    })
}

/// The revset of the cycle's branch: the commits `bookmark` reaches,
/// and those above it up to the work `@-`, a commit made by hand not
/// having advanced it, that no other local bookmark reaches.
fn branch_revset(bookmark: &str) -> String {
    let own = format!("bookmarks(exact:\"{bookmark}\")");
    format!("((::({own}) | ({own})::@-) ~ ::(bookmarks() ~ {own}))")
}

/// The titles of the commits on the cycle's branch in `repo`, oldest
/// first: the commits `bookmark` reaches, and those above it up to the
/// work `@-`, that no other local bookmark reaches, so no destination
/// is named or stored, less a working copy not yet described.
pub(crate) fn branch_titles(
    repo: &std::path::Path,
    bookmark: &str,
) -> Result<Vec<String>, Box<dyn std::error::Error>> {
    let mut titles = Vec::new();
    for cid in jj::cids_of(repo, &branch_revset(bookmark))? {
        let desc = jj::desc_of(repo, &cid)?;
        let title = desc.lines().next().unwrap_or_default().trim_end();
        if !title.is_empty() {
            titles.push(title.to_string());
        }
    }
    Ok(titles)
}

/// The bookmark of the cycle in progress in `r`'s workspace: the one
/// named, else the slug of the title in `TODO.md`, refused when the
/// work repo has no such bookmark.
pub(crate) fn cycle_bookmark(
    r: &Running,
    stage: &str,
) -> Result<String, Box<dyn std::error::Error>> {
    let name = match &r.bookmark {
        Some(name) => name.clone(),
        None => {
            let path = r.work.join(crate::commit::RECORD);
            let todo = std::fs::read_to_string(&path)
                .map_err(|e| format!("cycle {stage}: {}: {e}", path.display()))?;
            let title = record::cycle_title(&todo).map_err(|e| format!("cycle {stage}: {e}"))?;
            crate::check::anchors::anchor_slug(&title)
        }
    };
    if !jj::local_bookmark_exists(&r.work, &name)? {
        return Err(format!(
            "cycle {stage}: the cycle's bookmark '{name}' is not in {}: name it, --bookmark <NAME>",
            r.work.display()
        )
        .into());
    }
    Ok(name)
}

/// `--ladder`: make the ladder from the rung headings and the cycle's
/// commits, and write it, or with a dry run print it.
fn ladder(r: &Running) -> Result<(), Box<dyn std::error::Error>> {
    let bookmark = cycle_bookmark(r, "--ladder")?;
    let commits = branch_titles(&r.work, &bookmark)?;
    let plan =
        record::plan_ladder(&r.work, &commits).map_err(|e| format!("cycle --ladder: {e}"))?;
    for line in &plan.ladder.lines {
        info!("{line}");
    }
    for finding in &plan.ladder.findings {
        warn!("cycle --ladder: {finding}");
    }
    match (&plan.edit, r.dry_run) {
        (None, _) => info!(
            "cycle --ladder: the ladder in {} is as the rungs make it",
            record::LADDER_FILE
        ),
        (Some(_), true) => info!(
            "cycle --ladder: [dry-run] write the ladder into {}",
            record::LADDER_FILE
        ),
        (Some(edit), false) => {
            std::fs::write(&edit.path, &edit.text)
                .map_err(|e| format!("cycle --ladder: {}: {e}", edit.path.display()))?;
            info!(
                "cycle --ladder: the ladder is written into {}",
                record::LADDER_FILE
            );
        }
    }
    Ok(())
}

/// `--open`: plan the record, make the bookmark, then write the
/// record, so a record that cannot be written makes no bookmark, and a
/// name in use writes no record.
/// What is wrong with `title` as a cycle title, a line each: one that
/// is no Conventional Commit, `<type>: <desc>` or `<type>(<scope>):
/// <desc>`, and one over 50 characters, the bookends then longer still.
/// Empty when it is right.
pub(crate) fn title_problems(title: &str) -> Vec<String> {
    let mut problems = Vec::new();
    let conventional = title.split_once(": ").is_some_and(|(kind, desc)| {
        let kind = kind.strip_suffix('!').unwrap_or(kind);
        let (kind, scope) = match kind.split_once('(') {
            Some((k, rest)) => (k, rest.strip_suffix(')')),
            None => (kind, Some("x")),
        };
        !kind.is_empty()
            && kind.chars().all(|c| c.is_ascii_lowercase())
            && scope.is_some_and(|s| !s.is_empty())
            && !desc.trim().is_empty()
    });
    if !conventional {
        problems.push(format!(
            "'{title}' is no Conventional Commit, `<type>: <desc>`, `feat: x` for one"
        ));
    }
    let n = title.chars().count();
    if n > 50 {
        problems.push(format!(
            "'{title}' is {n} characters, over the 50 a title keeps to, its bookends longer still"
        ));
    }
    problems
}

fn open(ctx: &mut Context, o: &OpenCycle) -> Result<(), Box<dyn std::error::Error>> {
    let dry_run = o.open.dry_run;
    if let Some(title) = &o.record {
        for problem in title_problems(title) {
            warn!("cycle --open: {problem}, and every commit of the cycle carries it");
        }
    }
    let plan = match &o.record {
        Some(title) => {
            record::plan_open(&o.open.work, title).map_err(|e| format!("cycle --open: {e}"))?
        }
        None => {
            info!("cycle --open: no record is written, the bookmark being made alone");
            record::OpenRecord::default()
        }
    };
    crate::open::open(ctx, &o.open)?;
    let tag = if dry_run {
        "cycle --open: [dry-run]"
    } else {
        "cycle --open:"
    };
    for line in &plan.did {
        info!("{tag} {line}");
    }
    if dry_run {
        return Ok(());
    }
    for edit in &plan.edits {
        std::fs::write(&edit.path, &edit.text)
            .map_err(|e| format!("cycle --open: {}: {e}", edit.path.display()))?;
    }
    if !plan.edits.is_empty() {
        info!(
            "cycle --open: the record is written and nothing is committed: plan the cycle in it, \
             and bump the version"
        );
    }
    Ok(())
}

/// A closing's body when none is given: `[closing] body` in the
/// config, its `{title}` the cycle title, else a sentence naming the
/// cycle, then the pointer to its record, [`with_pointer`].
fn closing_body(repo: &std::path::Path, cycle: &str) -> Result<String, Box<dyn std::error::Error>> {
    let configured = crate::config_md::load(repo)?
        .and_then(|cfg| crate::toml_simple::toml_get(&cfg.map, "closing.body").cloned());
    let body = match configured {
        Some(body) => body,

toolUseResult.stdout:
                .map_err(|e| e.to_string())?;
            match repos.as_slice() {
                [repo] => Ok((repo.clone(), None)),
                other => Err(format!("cycle: expected one repo, got {}", other.len())),
            }
        }
    }
}

/// The agent repo a commit is made beside, and whether its commit is
/// made now, by `-s`, required: refused when it is left out, and when
/// it asks for a pair where there is none or a plain commit where
/// there is one.
fn commit_scope(
    scope: Option<&RepoScope>,
    agent: Option<PathBuf>,
    stage: &str,
) -> Result<Option<(PathBuf, bool)>, String> {
    match (scope, agent) {
        (None, _) => Err(format!(
            "cycle {stage}: -s is required, which repos: `b|both`, `w|work`, or `p|por`"
        )),
        (Some(RepoScope::Por), None) => Ok(None),
        (Some(RepoScope::Por), Some(_)) => Err(format!(
            "cycle {stage} -s p: this is a dual workspace, whose rung is a pair: -s b or -s w"
        )),
        (Some(RepoScope::Sides(_)), None) => Err(format!(
            "cycle {stage}: this is a plain repo, with no agent repo to pair with: -s p"
        )),
        (Some(RepoScope::Sides(sides)), Some(agent)) => Ok(Some((agent, sides.is_both()))),
    }
}

/// What `--close` lacks, every piece at once, so one refusal names all
/// of it: the shape, and with `--single-step` the body its one commit
/// needs. `None` when nothing is.
fn close_missing(a: &CycleArgs) -> Option<String> {
    let bodied = a.body.is_some() || a.default_body;
    let mut missing: Vec<&str> = Vec::new();
    if !a.single_step && !a.multi_step {
        missing.push(
            "the cycle's shape, --single-step, its one commit, or --multi-step, a ladder whose \
             closing is its own commit, which the branch's commits check and, with one commit, \
             the opening, it decides",
        );
        if !bodied {
            missing.push("with --single-step, --body or --default-body");
        }
    } else if a.single_step && !bodied {
        missing.push(
            "--body, the problem and solution of the one commit, which holds the work, or \
             --default-body for the pointer at the record",
        );
    }
    match missing.as_slice() {
        [] => None,
        [one] => Some(format!("cycle --close: it needs {one}")),
        many => Some(format!("cycle --close: it needs {}", many.join("; and "))),
    }
}

impl CycleArgs {
    /// The cycle a stage after `--open` works on.
    fn running(&self, work: PathBuf) -> Running {
        Running {
            work,
            bookmark: self.bookmark.clone(),
            dry_run: self.dry_run.value,
        }
    }

    /// `--open`'s params.
    fn open_params(&self, work: PathBuf, agent: Option<PathBuf>) -> Result<CycleParams, String> {
        if self.title.is_none() && self.bookmark.is_none() {
            return Err("cycle --open: --title or --bookmark names the bookmark".into());
        }
        let bookmark = crate::open::bookmark_name(self.bookmark.as_deref(), self.title.as_deref())?;
        if let Some(t) = &self.title {
            crate::commit::refuse_suffixed(t, "cycle --open --title")
                .map_err(|e| e.replacen("commit ", "", 1))?;
        }
        Ok(CycleParams::Open(OpenCycle {
            open: OpenParams {
                work,
                agent,
                bookmark,
                dry_run: self.dry_run.value,
            },
            record: match (&self.title, self.no_record) {
                (Some(t), false) => Some(t.trim().to_string()),
                _ => None,
            },
        }))
    }

    /// `--land`'s params, `None` when it is not asked for. With `alone`
    /// the title and body are the merge commit's, and after `--close`
    /// they are the closing's.
    fn land_params(
        &self,
        work: PathBuf,
        agent: Option<PathBuf>,
        alone: bool,
    ) -> Result<Option<LandCycle>, String> {
        let Some(dest) = &self.land else {
            return Ok(None);
        };
        if matches!(&self.scope, Some(RepoScope::Sides(s)) if !s.is_both()) {
            return Err(
                "cycle --land -s w: a work-only Land would publish trailers naming agent commits \
                 its agent half may not have published: -s b"
                    .into(),
            );
        }
        commit_scope(self.scope.as_ref(), agent.clone(), "--land")?;
        if alone && self.same_version {
            return Err("cycle --land: it takes no --same-version, a Land bumping nothing".into());
        }
        if alone && (self.title.is_some() || self.body.is_some()) && !self.merge {
            return Err(
                "cycle --land: a Land makes no commit of its own, so --title and --body are \
                 --merge's, the merge commit's"
                    .into(),
            );
        }
        let body = match (&self.body, alone) {
            (Some(b), true) => Some(crate::desc_helpers::read_body(b, "cycle --land")?),
            _ => None,
        };
        Ok(Some(LandCycle {
            running: self.running(work),
            agent,
            dest: dest.clone(),
            merge: self.merge,
            skip: self.skip,
            delete_intermediate: self.delete_intermediate_bookmarks,
            push: self.push,
            title: self.title.clone().filter(|_| alone),
            body,
        }))
    }

    /// A commit's params, `--commit`'s and `--close`'s alike.
    fn rung(
        &self,
        work: PathBuf,
        agent: Option<PathBuf>,
        stage: &str,
    ) -> Result<CommitRung, String> {
        let body = match &self.body {
            Some(b) => Some(crate::desc_helpers::read_body(
                b,
                &format!("cycle {stage}"),
            )?),
            None => None,
        };
        if self.title.as_deref().is_some_and(|t| t.trim().is_empty())
            || body.as_deref().is_some_and(|b| b.trim().is_empty())
        {
            return Err(format!(
                "cycle {stage}: a --title or --body given is not blank"
            ));
        }
        Ok(CommitRung {
            agent: commit_scope(self.scope.as_ref(), agent, stage)?,
            running: self.running(work),
            title: self.title.as_ref().map(|t| t.trim().to_string()),
            body,
            push: self.push,
            same_version: self.same_version,
        })
    }
}

impl TryFrom<&CycleArgs> for CycleParams {
    type Error = String;

    /// Resolve the workspace and the stage asked for.
    fn try_from(a: &CycleArgs) -> Result<Self, String> {
        let (work, agent) = resolve_repos(a.repo.as_deref())?;
        let only = |stage: &str, given: &[(&str, bool)]| match given.iter().find(|(_, g)| *g) {
            Some((flag, _)) => Err(format!("cycle {stage}: it takes no {flag}")),
            None => Ok(()),
        };
        let commits = [
            ("--same-version", a.same_version),
            ("-s", a.scope.is_some()),
            ("--push", a.push),
            ("--body", a.body.is_some()),
        ];
        if a.open {
            only("--open", &commits)?;
            a.open_params(work, agent)
        } else if a.ladder {
            only("--ladder", &commits)?;
            Ok(CycleParams::Ladder(a.running(work)))
        } else if a.status {
            only("--status", &commits)?;
            Ok(CycleParams::Status(a.running(work)))
        } else if let Some(heads) = &a.close {
            // A dead end's shape is wrong whatever else is given, so it is
            // said first.
            if a.dead_end && a.single_step {
                return Err(
                    "cycle --close --dead-end: a dead end closes the commits a cycle made with a \
                     closing commit of its own: --multi-step"
                        .into(),
                );
            }
            if let Some(missing) = close_missing(a) {
                return Err(missing);
            }
            let land = a.land_params(work.clone(), agent.clone(), false)?;
            let mut rung = a.rung(work, agent, "--close")?;
            // With a Land the push is the Land's, the destination's.
            rung.push = rung.push && land.is_none();
            Ok(CycleParams::Close(CloseCycle {
                rung,
                heads: heads.clone(),
                trapezoid: a.trapezoid.clone(),
                default_body: a.default_body,
                dead_end: a.dead_end,
                single_step: a.single_step,
                land,
            }))
        } else if let Some(land) = a.land_params(work.clone(), agent.clone(), true)? {
            Ok(CycleParams::Land(land))
        } else if a.commit {
            Ok(CycleParams::Commit(a.rung(work, agent, "--commit")?))
        } else {
            only(
                "--push",
                &[
                    ("--same-version", a.same_version),
                    ("--body", a.body.is_some()),
                    ("--title", a.title.is_some()),
                ],
            )?;
            if matches!(&a.scope, Some(RepoScope::Sides(s)) if !s.is_both()) {
                return Err(
                    "cycle --push -s w: the work half alone would publish trailers naming agent \
                     commits not yet published: -s b"
                        .into(),
                );
            }
            Ok(CycleParams::Push(PushCycle {
                agent: commit_scope(a.scope.as_ref(), agent, "--push")?.map(|(a, _)| a),
                running: a.running(work),
            }))
        }
    }
}

impl SubcommandRunner for CycleArgs {
    type Params = CycleParams;

    /// Delegate to the `TryFrom<&CycleArgs>` impl above.
    fn to_params(&self) -> Result<Self::Params, String> {
        CycleParams::try_from(self)
    }

    /// Run the `cycle` op.
    fn run(ctx: &mut Context, params: &Self::Params) -> Result<(), Box<dyn std::error::Error>> {
        cycle(ctx, params)
    }
}

/// Entry point: the stage asked for.
pub fn cycle(ctx: &mut Context, params: &CycleParams) -> Result<(), Box<dyn std::error::Error>> {
    debug!("cycle: enter {params:?}");
    match params {
        CycleParams::Open(o) => open(ctx, o),
        CycleParams::Ladder(r) => ladder(r),
        CycleParams::Commit(c) => commit_rung(ctx, c),
        CycleParams::Close(c) => close(ctx, c),
        CycleParams::Land(l) => land(ctx, l),
        CycleParams::Push(p) => push(ctx, p),
        CycleParams::Status(r) => {
            for line in status(r)? {
                info!("{line}");
            }
            Ok(())
        }
    }
}

/// The opening's body when none is given: `[opening] body` in the
/// config, its `{title}` the cycle title, else a sentence naming the
/// cycle, then the pointer to its record, [`with_pointer`].
fn opening_body(repo: &std::path::Path, cycle: &str) -> Result<String, Box<dyn std::error::Error>> {
    let configured = crate::config_md::load(repo)?
        .and_then(|cfg| crate::toml_simple::toml_get(&cfg.map, "opening.body").cloned());
    let body = match configured {
        Some(body) => body,
        None => "Opens the cycle \"{title}\".".to_string(),
    };
    Ok(with_pointer(&body.replace("{title}", cycle), cycle))
}

/// A bookend's body with the pointer to the cycle's record, its own
/// paragraph, two lines, the second the cycle's heading exactly as
/// written in the record, so a search finds it at any commit.
fn with_pointer(body: &str, cycle: &str) -> String {
    format!(
        "{}\n\nSee details in {}:\n### {cycle}",
        body.trim_end(),
        crate::commit::RECORD
    )
}

/// The params of the commit a stage makes, `vc-x1 commit`'s: the pair
/// or the plain repo, the description, and the cycle's bookmark the
/// one advanced.
fn commit_params(
    c: &CommitRung,
    title: String,
    body: String,
    bookmark: String,
) -> crate::commit::CommitParams {
    let target = match &c.agent {
        Some((agent, agent_now)) => crate::commit::Target::Pair {
            pair: crate::pair::Pair {
                work: c.running.work.clone(),
                agent: agent.clone(),
            },
            agent_now: *agent_now,
        },
        None => crate::commit::Target::Por(c.running.work.clone()),
    };
    crate::commit::CommitParams {
        target,
        title: Some(title),
        body: Some(body),
        advance: crate::commit::Advance::Named(bookmark),
        push: c.push,
        no_url_trailer: false,
        dry_run: c.running.dry_run,
        rev: None,
        covers: None,
        allow_empty: false,
        same_version: c.same_version,
        land_follows: false,
    }
}

/// `--commit`: commit the working copies as a rung of the cycle in
/// progress. The cycle's first commit is its opening, titled and
/// bodied by default, and any other is a work rung, whose title is a
/// rung heading not yet committed. The ladder is rewritten first, the
/// rung done, so the commit carries it, and the cycle's bookmark is
/// the one advanced. Every check is made before the ladder is written.
fn commit_rung(ctx: &mut Context, c: &CommitRung) -> Result<(), Box<dyn std::error::Error>> {
    let stage = "--commit";
    let r = &c.running;
    let work = r.work.as_path();
    let bookmark = cycle_bookmark(r, stage)?;
    let commits = branch_titles(work, &bookmark)?;
    let path = work.join(crate::commit::RECORD);
    let todo = std::fs::read_to_string(&path)
        .map_err(|e| format!("cycle {stage}: {}: {e}", path.display()))?;
    let cycle = record::cycle_title(&todo).map_err(|e| format!("cycle {stage}: {e}"))?;
    let rungs = record::rung_titles(&todo).map_err(|e| format!("cycle {stage}: {e}"))?;
    let (opening, closing) = (format!("{cycle} opening"), format!("{cycle} closing"));
    let first = commits.is_empty();
    let title = match (&c.title, first) {
        (None, true) => opening.clone(),
        (Some(t), true) if *t == opening => opening.clone(),
        (Some(t), true) => {
            return Err(format!(
                "cycle {stage}: the cycle has no commit yet, so this one is its opening, \
                 '{opening}', and not '{t}': leave --title out"
            )
            .into());
        }
        (None, false) => {
            return Err(format!(
                "cycle {stage}: the opening is committed, so this is a work rung, which gives \
                 --title, a heading under `#### Rungs`, and --body"
            )
            .into());
        }
        (Some(t), false) => t.clone(),
    };
    if title == closing {
        return Err(format!(
            "cycle {stage}: '{title}' is the cycle's closing, which `cycle --close` makes"
        )
        .into());
    }
    if commits.contains(&title) {
        return Err(format!(
            "cycle {stage}: the rung '{title}' is committed already: `vc-x1 squash` continues it"
        )
        .into());
    }
    if !rungs.contains(&title) {
        return Err(format!(
            "cycle {stage}: '{title}' is no rung of the cycle, a `##### ` heading under `#### \
             Rungs` in {}: write its heading first",
            crate::commit::RECORD
        )
        .into());
    }
    let body = match (&c.body, first) {
        (Some(b), _) => b.clone(),
        (None, true) => opening_body(work, &cycle)?,
        (None, false) => {
            return Err(format!(
                "cycle {stage}: a work rung gives --body, its problem and solution"
            )
            .into());
        }
    };
    crate::pair::refuse_conflicts(work, "cycle --commit", "work")?;
    if jj::is_empty(work, "@")? {
        return Err(format!(
            "cycle {stage}: nothing to commit, the work repo's @ is empty ('{}')",
            work.display()
        )
        .into());
    }
    crate::commit::check_version(work, "@", c.same_version, "cycle --commit")?;
    let mut with = commits.clone();
    with.push(title.clone());
    let plan = record::plan_ladder(work, &with).map_err(|e| format!("cycle {stage}: {e}"))?;
    for finding in &plan.ladder.findings {
        warn!("cycle {stage}: {finding}");
    }
    info!(
        "cycle {stage}: {} '{title}' on '{bookmark}'",
        if first { "the opening" } else { "the rung" }
    );
    let params = commit_params(c, title, body, bookmark);
    let Some(edit) = plan.edit.as_ref().filter(|_| !r.dry_run) else {
        if plan.edit.is_some() {
            info!(
                "cycle {stage}: [dry-run] rewrite the ladder in {}, the rung done",
                record::LADDER_FILE
            );
        }
        return crate::commit::commit(ctx, &params);
    };
    // The ladder is written before the commit, which carries it, and
    // put back as it was when the commit is not made.
    let old = std::fs::read_to_string(&edit.path)?;
    std::fs::write(&edit.path, &edit.text)?;
    info!(
        "cycle {stage}: the ladder in {} is rewritten, the rung done",
        record::LADDER_FILE
    );
    crate::commit::commit(ctx, &params).inspect_err(|_| {
        if let Err(e) = std::fs::write(&edit.path, &old) {
            warn!(
                "cycle {stage}: the ladder in {} was not put back: {e}",
                edit.path.display()
            );
        }
    })
}

/// The revset of the cycle's branch: the commits `bookmark` reaches,
/// and those above it up to the work `@-`, a commit made by hand not
/// having advanced it, that no other local bookmark reaches.
fn branch_revset(bookmark: &str) -> String {
    let own = format!("bookmarks(exact:\"{bookmark}\")");
    format!("((::({own}) | ({own})::@-) ~ ::(bookmarks() ~ {own}))")
}

/// The titles of the commits on the cycle's branch in `repo`, oldest
/// first: the commits `bookmark` reaches, and those above it up to the
/// work `@-`, that no other local bookmark reaches, so no destination
/// is named or stored, less a working copy not yet described.
pub(crate) fn branch_titles(
    repo: &std::path::Path,
    bookmark: &str,
) -> Result<Vec<String>, Box<dyn std::error::Error>> {
    let mut titles = Vec::new();
    for cid in jj::cids_of(repo, &branch_revset(bookmark))? {
        let desc = jj::desc_of(repo, &cid)?;
        let title = desc.lines().next().unwrap_or_default().trim_end();
        if !title.is_empty() {
            titles.push(title.to_string());
        }
    }
    Ok(titles)
}

/// The bookmark of the cycle in progress in `r`'s workspace: the one
/// named, else the slug of the title in `TODO.md`, refused when the
/// work repo has no such bookmark.
pub(crate) fn cycle_bookmark(
    r: &Running,
    stage: &str,
) -> Result<String, Box<dyn std::error::Error>> {
    let name = match &r.bookmark {
        Some(name) => name.clone(),
        None => {
            let path = r.work.join(crate::commit::RECORD);
            let todo = std::fs::read_to_string(&path)
                .map_err(|e| format!("cycle {stage}: {}: {e}", path.display()))?;
            let title = record::cycle_title(&todo).map_err(|e| format!("cycle {stage}: {e}"))?;
            crate::check::anchors::anchor_slug(&title)
        }
    };
    if !jj::local_bookmark_exists(&r.work, &name)? {
        return Err(format!(
            "cycle {stage}: the cycle's bookmark '{name}' is not in {}: name it, --bookmark <NAME>",
            r.work.display()
        )
        .into());
    }
    Ok(name)
}

/// `--ladder`: make the ladder from the rung headings and the cycle's
/// commits, and write it, or with a dry run print it.
fn ladder(r: &Running) -> Result<(), Box<dyn std::error::Error>> {
    let bookmark = cycle_bookmark(r, "--ladder")?;
    let commits = branch_titles(&r.work, &bookmark)?;
    let plan =
        record::plan_ladder(&r.work, &commits).map_err(|e| format!("cycle --ladder: {e}"))?;
    for line in &plan.ladder.lines {
        info!("{line}");
    }
    for finding in &plan.ladder.findings {
        warn!("cycle --ladder: {finding}");
    }
    match (&plan.edit, r.dry_run) {
        (None, _) => info!(
            "cycle --ladder: the ladder in {} is as the rungs make it",
            record::LADDER_FILE
        ),
        (Some(_), true) => info!(
            "cycle --ladder: [dry-run] write the ladder into {}",
            record::LADDER_FILE
        ),
        (Some(edit), false) => {
            std::fs::write(&edit.path, &edit.text)
                .map_err(|e| format!("cycle --ladder: {}: {e}", edit.path.display()))?;
            info!(
                "cycle --ladder: the ladder is written into {}",
                record::LADDER_FILE
            );
        }
    }
    Ok(())
}

/// `--open`: plan the record, make the bookmark, then write the
/// record, so a record that cannot be written makes no bookmark, and a
/// name in use writes no record.
/// What is wrong with `title` as a cycle title, a line each: one that
/// is no Conventional Commit, `<type>: <desc>` or `<type>(<scope>):
/// <desc>`, and one over 50 characters, the bookends then longer still.
/// Empty when it is right.
pub(crate) fn title_problems(title: &str) -> Vec<String> {
    let mut problems = Vec::new();
    let conventional = title.split_once(": ").is_some_and(|(kind, desc)| {
        let kind = kind.strip_suffix('!').unwrap_or(kind);
        let (kind, scope) = match kind.split_once('(') {
            Some((k, rest)) => (k, rest.strip_suffix(')')),
            None => (kind, Some("x")),
        };
        !kind.is_empty()
            && kind.chars().all(|c| c.is_ascii_lowercase())
            && scope.is_some_and(|s| !s.is_empty())
            && !desc.trim().is_empty()
    });
    if !conventional {
        problems.push(format!(
            "'{title}' is no Conventional Commit, `<type>: <desc>`, `feat: x` for one"
        ));
    }
    let n = title.chars().count();
    if n > 50 {
        problems.push(format!(
            "'{title}' is {n} characters, over the 50 a title keeps to, its bookends longer still"
        ));
    }
    problems
}

fn open(ctx: &mut Context, o: &OpenCycle) -> Result<(), Box<dyn std::error::Error>> {
    let dry_run = o.open.dry_run;
    if let Some(title) = &o.record {
        for problem in title_problems(title) {
            warn!("cycle --open: {problem}, and every commit of the cycle carries it");
        }
    }
    let plan = match &o.record {
        Some(title) => {
            record::plan_open(&o.open.work, title).map_err(|e| format!("cycle --open: {e}"))?
        }
        None => {
            info!("cycle --open: no record is written, the bookmark being made alone");
            record::OpenRecord::default()
        }
    };
    crate::open::open(ctx, &o.open)?;
    let tag = if dry_run {
        "cycle --open: [dry-run]"
    } else {
        "cycle --open:"
    };
    for line in &plan.did {
        info!("{tag} {line}");
    }
    if dry_run {
        return Ok(());
    }
    for edit in &plan.edits {
        std::fs::write(&edit.path, &edit.text)
            .map_err(|e| format!("cycle --open: {}: {e}", edit.path.display()))?;
    }
    if !plan.edits.is_empty() {
        info!(
            "cycle --open: the record is written and nothing is committed: plan the cycle in it, \
             and bump the version"
        );
    }
    Ok(())
}

/// A closing's body when none is given: `[closing] body` in the
/// config, its `{title}` the cycle title, else a sentence naming the
/// cycle, then the pointer to its record, [`with_pointer`].
fn closing_body(repo: &std::path::Path, cycle: &str) -> Result<String, Box<dyn std::error::Error>> {
    let configured = crate::config_md::load(repo)?
        .and_then(|cfg| crate::toml_simple::toml_get(&cfg.map, "closing.body").cloned());
    let body = match configured {
        Some(body) => body,

content.content:
//! The cycle-record's mechanical edits, as text: what `cycle --open`
//! writes into `TODO.md` and `zTOC.md`.
//!
//! - The record's shape is the agent-files', so the tool knows it
//!   without knowing the work: `TODO.md`'s `## In Progress`, `## Todo`,
//!   and `## Closed`, and `zTOC.md`'s `## Ladder`.
//! - Every function here takes a file's text and returns its new
//!   text, so a refusal comes before anything is written and a dry
//!   run is the same code.
//! - A heading inside a fenced code block is not one, as the closing's
//!   record move has it.

use std::path::{Path, PathBuf};

use crate::check::anchors::anchor_slug;
use crate::commit::{NONE_IN_PROGRESS, RECORD, section};

/// The ladder's file, beside the record.
pub(crate) const LADDER_FILE: &str = "zTOC.md";

/// The ladder's heading in [`LADDER_FILE`].
const LADDER: &str = "## Ladder";

/// What an item of the scaffold reads until it is written.
const TO_WRITE: &str = "_To write._";

/// The lines of `text` outside fenced code, each with its byte offset
/// and its text less the line ending.
fn prose_lines(text: &str) -> impl Iterator<Item = (usize, &str)> {
    let mut fenced = false;
    let mut at = 0;
    text.split_inclusive('\n').filter_map(move |line| {
        let start = at;
        at += line.len();
        let bare = line.trim_end_matches(['\n', '\r']);
        if bare.starts_with("```") {
            fenced = !fenced;
            return None;
        }
        (!fenced).then_some((start, bare))
    })
}

/// A section's body with its content replaced: the intro, everything
/// before the first line `starts` accepts, is kept, then `content`,
/// none when it is empty, and a blank line before the next heading
/// unless the file ends there.
fn with_content(
    text: &str,
    (start, end): (usize, usize),
    starts: impl Fn(&str) -> bool,
    content: &str,
) -> String {
    let body = &text[start..end];
    let from = prose_lines(body)
        .find(|(_, l)| starts(l))
        .map_or(body.len(), |(at, _)| at);
    let intro = body[..from].trim_end();
    let content = content.trim_end();
    let mut new = String::new();
    if !intro.trim().is_empty() {
        new.push_str(intro);
        new.push('\n');
    }
    if !content.is_empty() {
        new.push('\n');
        new.push_str(content);
        new.push('\n');
    }
    if end != text.len() {
        new.push('\n');
    }
    format!("{}{new}{}", &text[..start], &text[end..])
}

/// The `## Todo` entry titled `title` in `text`: its byte range, the
/// heading to the next entry or the section's end, and its text.
fn todo_entry(text: &str, title: &str) -> Option<((usize, usize), String)> {
    let (start, end) = section(text, "## Todo")?;
    let body = &text[start..end];
    let heading = format!("### {}", title.trim());
    let mut lines = prose_lines(body).skip_while(|(_, l)| l.trim_end() != heading);
    let (from, first) = lines.next()?;
    let to = lines
        .find(|(_, l)| l.starts_with("### "))
        .map_or(body.len(), |(at, _)| at);
    let entry = body[from + first.len()..to].trim().to_string();
    Some(((start + from, start + to), entry))
}

/// The `## In Progress` scaffold of the cycle `title`: the title, the
/// items, `problem` under Problem, and the opening and closing rung
/// subsections, in the specimen's shape.
fn scaffold(title: &str, problem: &str) -> String {
    let problem = if problem.is_empty() {
        TO_WRITE
    } else {
        problem
    };
    format!(
        "### {title}\n\n\
         #### Problem\n\n{problem}\n\n\
         #### Solution\n\n{TO_WRITE}\n\n\
         #### Acceptance check\n\n{TO_WRITE}\n\n\
         #### Deliberation\n\n_None._\n\n\
         #### Rungs\n\n\
         The rung subsections, in the ladder's order. The ladder itself is in `{LADDER_FILE} > \
         {LADDER}`.\n\n\
         ##### {title} opening\n\n\
         The cycle's first commit, carrying its plan: the bookmark, the last cycle's record \
         deleted, and the\nTodo entry moved into this block.\n\n\
         ##### {title} closing\n\n\
         Closing out the cycle.\n"
    )
}

/// `TODO.md`'s text with the cycle `title` opened, and what was done,
/// a line each: what `## Closed` holds is deleted, the `## Todo` entry
/// titled so is moved into an `## In Progress` scaffold, an empty one
/// when none matches. Refused when there is no `## In Progress` or a
/// cycle is in it.
pub(crate) fn opened_record(text: &str, title: &str) -> Result<(String, Vec<String>), String> {
    let title = title.trim();
    let entry = |l: &str| l.starts_with("### ");
    let content = |l: &str| entry(l) || l == NONE_IN_PROGRESS;
    let progress = section(text, "## In Progress")
        .ok_or_else(|| format!("{RECORD} has no `## In Progress` to open the cycle in"))?;
    if let Some((_, running)) = prose_lines(&text[progress.0..progress.1]).find(|(_, l)| entry(l)) {
        return Err(format!(
            "{RECORD} has a cycle in progress, '{}': it closes first",
            running.trim_start_matches("### ")
        ));
    }
    let mut did = Vec::new();
    let found = todo_entry(text, title);
    let problem = match &found {
        Some((_, entry)) => {
            did.push(format!(
                "move the `## Todo` entry '{title}' into `## In Progress`"
            ));
            entry.as_str()
        }
        None => {
            did.push(format!(
                "no `## Todo` entry is titled '{title}', so `## In Progress` gets an empty scaffold"
            ));
            ""
        }
    };
    // The edits, each a range and the text that replaces it, applied
    // last first, so an earlier one's offsets still hold.
    let mut edits: Vec<((usize, usize), String)> = Vec::new();
    let opened = with_content(text, progress, content, &scaffold(title, problem));
    edits.push((
        progress,
        opened[progress.0..opened.len() - (text.len() - progress.1)].to_string(),
    ));
    if let Some((range, _)) = found {
        edits.push((range, String::new()));
    }
    match section(text, "## Closed") {
        Some(closed) => {
            let emptied = with_content(text, closed, entry, "");
            let body = emptied[closed.0..emptied.len() - (text.len() - closed.1)].to_string();
            if body != text[closed.0..closed.1] {
                did.insert(0, "delete what `## Closed` holds".to_string());
            }
            edits.push((closed, body));
        }
        None => did.insert(0, "no `## Closed`, so nothing is deleted".to_string()),
    }
    edits.sort_by_key(|((start, _), _)| std::cmp::Reverse(*start));
    let mut new = text.to_string();
    for ((start, end), with) in edits {
        new.replace_range(start..end, &with);
    }
    Ok((new, did))
}

/// The items of the cycle in progress in `TODO.md`'s `text` still
/// reading the scaffold's placeholder: Problem, Solution, and
/// Acceptance check, in that order.
pub(crate) fn unwritten_items(text: &str) -> Vec<&'static str> {
    let Some((start, end)) = section(text, "## In Progress") else {
        return Vec::new();
    };
    let body = &text[start..end];
    let lines: Vec<(usize, &str)> = prose_lines(body).collect();
    ["Problem", "Solution", "Acceptance check"]
        .into_iter()
        .filter(|item| {
            let heading = format!("#### {item}");
            let Some(i) = lines.iter().position(|(_, l)| l.trim_end() == heading) else {
                return false;
            };
            let text: Vec<&str> = lines[i + 1..]
                .iter()
                .take_while(|(_, l)| !l.starts_with('#'))
                .map(|(_, l)| l.trim())
                .filter(|l| !l.is_empty())
                .collect();
            text == [TO_WRITE]
        })
        .collect()
}

/// `TODO.md`'s text with the `#### Rungs` item of the cycle `## Closed`
/// holds removed, its heading to the next heading of its level or
/// above, for a single-step cycle, whose one commit has no rungs.
pub(crate) fn without_closed_rungs(text: &str) -> String {
    let Some((start, end)) = section(text, "## Closed") else {
        return text.to_string();
    };
    let body = &text[start..end];
    let mut lines = prose_lines(body).skip_while(|(_, l)| l.trim_end() != "#### Rungs");
    let Some((from, _)) = lines.next() else {
        return text.to_string();
    };
    let above = |l: &str| {
        ["# ", "## ", "### ", "#### "]
            .iter()
            .any(|h| l.starts_with(h))
    };
    let to = lines
        .find(|(_, l)| above(l))
        .map_or(body.len(), |(at, _)| at);
    let kept = format!("{}{}", body[..from].trim_end(), "\n\n");
    let tail = &body[to..];
    let new_body = if tail.is_empty() && end == text.len() {
        format!("{}\n", kept.trim_end())
    } else if tail.is_empty() {
        kept
    } else {
        format!("{kept}{tail}")
    };
    format!("{}{new_body}{}", &text[..start], &text[end..])
}

/// A ladder's line for a rung not yet started: the title linked to
/// its subsection in the record.
fn rung_link(title: &str) -> String {
    format!("[{title}]({RECORD}#{})", anchor_slug(title))
}

/// `zTOC.md`'s text with the ladder of a cycle just opened in place of
/// the last cycle's: the opening and the closing, neither marked. Refused
/// when there is no `## Ladder`.
pub(crate) fn opened_ladder(text: &str, title: &str) -> Result<String, String> {
    let title = title.trim();
    let rungs = [format!("{title} opening"), format!("{title} closing")];
    // A new cycle replaces the last one's ladder whatever its lines
    // were, so the grammar is not asked of them.
    let ladder = section(text, LADDER)
        .ok_or_else(|| format!("{LADDER_FILE} has no `{LADDER}` to write the cycle's ladder in"))?;
    let made = ladder_of(title, &rungs, &[])?;
    Ok(with_content(text, ladder, |_| true, &made.lines.join("\n")))
}

/// The title of the cycle in progress in `TODO.md`'s `text`, its
/// `### ` heading under `## In Progress`. Refused when there is none.
pub(crate) fn cycle_title(text: &str) -> Result<String, String> {
    let (start, end) = section(text, "## In Progress")
        .ok_or_else(|| format!("{RECORD} has no `## In Progress`"))?;
    prose_lines(&text[start..end])
        .find_map(|(_, l)| l.strip_prefix("### "))
        .map(|t| t.trim().to_string())
        .ok_or_else(|| format!("{RECORD} has no cycle in progress: `cycle --open` opens one"))
}

/// The title of the cycle `## Closed` holds in `TODO.md`'s `text`, the
/// last one closed, `None` when it holds none.
pub(crate) fn closed_title(text: &str) -> Option<String> {
    let (start, end) = section(text, "## Closed")?;
    prose_lines(&text[start..end])
        .find_map(|(_, l)| l.strip_prefix("### "))
        .map(|t| t.trim().to_string())
}

/// The rung titles of the cycle in progress, in their order: the
/// `##### ` headings under its `#### Rungs`, to the next heading of
/// that level or above. Refused when there is no `#### Rungs` or it
/// holds no rung.
pub(crate) fn rung_titles(text: &str) -> Result<Vec<String>, String> {
    let (start, end) = section(text, "## In Progress")
        .ok_or_else(|| format!("{RECORD} has no `## In Progress`"))?;
    let mut lines =
        prose_lines(&text[start..end]).skip_while(|(_, l)| l.trim_end() != "#### Rungs");
    if lines.next().is_none() {
        return Err(format!(
            "{RECORD}'s cycle has no `#### Rungs` heading to read its rungs from"
        ));
    }
    let above = |l: &str| {
        ["# ", "## ", "### ", "#### "]
            .iter()
            .any(|h| l.starts_with(h))
    };
    let rungs: Vec<String> = lines
        .take_while(|(_, l)| !above(l))
        .filter_map(|(_, l)| l.strip_prefix("##### "))
        .map(|t| t.trim().to_string())
        .collect();
    if rungs.is_empty() {
        return Err(format!(
            "{RECORD}'s `#### Rungs` holds no rung, a `##### <title>` heading each"
        ));
    }
    Ok(rungs)
}

/// A ladder made: its lines, and what a reader should know that the
/// lines do not refuse, a line each.
#[derive(Debug, PartialEq, Eq)]
pub(crate) struct Ladder {
    pub lines: Vec<String>,
    pub findings: Vec<String>,
}

/// The ladder of the cycle `cycle`, a line per rung in `rungs`' order,
/// `commits` being the titles of the commits on its branch. A rung is
/// `(done)`, numbered by its position, when a commit has its title, and
/// every other rung is its link alone, so the first unmarked rung is
/// the next and no line claims work not yet begun. A single-step cycle,
/// its one commit under the bare cycle title, is one unlinked rung.
///
/// Refused: a title written twice, a ladder not opened by the cycle
/// title plus " opening" or not closed by it plus " closing", and a
/// commit whose title is no rung's, each naming what it found. A done
/// rung below the first rung not done is a finding, the ladder still
/// made.
pub(crate) fn ladder_of(
    cycle: &str,
    rungs: &[String],
    commits: &[String],
) -> Result<Ladder, String> {
    for (i, r) in rungs.iter().enumerate() {
        if rungs[..i].contains(r) {
            return Err(format!(
                "the rung '{r}' is written twice under `#### Rungs`"
            ));
        }
    }
    let (opening, closing) = (format!("{cycle} opening"), format!("{cycle} closing"));
    if rungs.first() != Some(&opening) {
        return Err(format!(
            "the first rung under `#### Rungs` is not the cycle's opening, '{opening}'"
        ));
    }
    if rungs.len() < 2 || rungs.last() != Some(&closing) {
        return Err(format!(
            "the last rung under `#### Rungs` is not the cycle's closing, '{closing}'"
        ));
    }
    let strays: Vec<&String> = commits
        .iter()
        .filter(|c| c.as_str() != cycle && !rungs.contains(c))
        .collect();
    if !strays.is_empty() {
        return Err(format!(
            "{} on the cycle's branch match no rung under `#### Rungs`, and every commit of a \
             cycle is a rung's: {}",
            if strays.len() == 1 {
                "a commit's title".to_string()
            } else {
                format!("{} commits' titles", strays.len())
            },
            strays
                .iter()
                .map(|s| format!("'{s}'"))
                .collect::<Vec<_>>()
                .join(", ")
        ));
    }
    if commits.iter().any(|c| c == cycle) {
        if commits.len() > 1 {
            return Err(format!(
                "the branch has a commit titled '{cycle}', a single-step cycle's one commit, \
                 beside {} more",
                commits.len() - 1
            ));
        }
        return Ok(Ladder {
            lines: vec![format!("- 0 (done) {cycle}")],
            findings: Vec::new(),
        });
    }
    let next = rungs.iter().position(|r| !commits.contains(r));
    let mut findings = Vec::new();
    let lines = rungs
        .iter()
        .enumerate()
        .map(|(i, r)| {
            let link = rung_link(r);
            if commits.contains(r) {
                if let Some(n) = next
                    && n < i
                {
                    findings.push(format!(
                        "the rung '{r}' is done and is below '{}', a rung not done",
                        rungs[n]
                    ));
                }
                format!("- {i} (done) {link}")
            } else {
                format!("- {link}")
            }
        })
        .collect();
    Ok(Ladder { lines, findings })
}

/// A ladder line with its link reduced to the title it shows,
/// `- 1 (done) [feat: x](TODO.md#feat-x)` to `- 1 (done) feat: x`,
/// for a terminal, where the link cannot be followed.
pub(crate) fn unlinked(line: &str) -> String {
    let Some(open) = line.find('[') else {
        return line.to_string();
    };
    let Some(close) = line[open..].find("](").map(|i| open + i) else {
        return line.to_string();
    };
    if !line.ends_with(')') {
        return line.to_string();
    }
    format!("{}{}", &line[..open], &line[open + 1..close])
}

/// Whether `line`, a left-margin bullet, is a rung by the ladder's
/// grammar: `- `, then optionally a number and `(done)`, then the
/// title, linked to its slug in the record or, for a single-step cycle,
/// bare. A number and `(current)`, which a `vc-x1` before 0.85.26 wrote
/// on the next rung, is read too, so a ladder from mid-cycle at an
/// upgrade is still a ladder and is rewritten without it.
fn is_rung(line: &str) -> bool {
    let Some(rest) = line.strip_prefix("- ") else {
        return false;
    };
    let digits = rest.len() - rest.trim_start_matches(|c: char| c.is_ascii_digit()).len();
    let rest = match digits {
        0 => rest,
        _ => {
            let after = &rest[digits..];
            match after
                .strip_prefix(" (current) ")
                .or_else(|| after.strip_prefix(" (done) "))
            {
                Some(title) => title,
                None => return false,
            }
        }
    };
    match rest.strip_prefix('[') {
        Some(linked) => linked
            .split_once(&format!("]({RECORD}#"))
            .and_then(|(title, slug)| Some((title, slug.strip_suffix(')')?)))
            .is_some_and(|(title, slug)| !title.is_empty() && slug == anchor_slug(title)),
        None => !rest.trim().is_empty() && rest == rest.trim() && !rest.contains("]("),
    }
}

/// `zTOC.md`'s text with `lines` as its ladder. Refused, with nothing
/// edited, when there is no `## Ladder`, or when a line of the ladder
/// there does not fit the grammar, each such line named: a rung is a
/// left-margin bullet, and anything else but a blank line and the
/// skeleton's `_None._` is a line the rewrite would lose.
pub(crate) fn written_ladder(text: &str, lines: &[String]) -> Result<String, String> {
    let ladder = section(text, LADDER)
        .ok_or_else(|| format!("{LADDER_FILE} has no `{LADDER}` to write the cycle's ladder in"))?;
    let misfits: Vec<String> = text[ladder.0..ladder.1]
        .lines()
        .filter(|l| !l.trim().is_empty() && l.trim() != "_None._" && !is_rung(l))
        .map(|l| format!("  {l}"))
        .collect();
    if !misfits.is_empty() {
        return Err(format!(
            "{LADDER_FILE}'s `{LADDER}` holds {} that a rung's grammar does not fit, `- [N \
             (done)] [<title>]({RECORD}#<slug>)`, so nothing is edited:\n{}",
            if misfits.len() == 1 {
                "a line".to_string()
            } else {
                format!("{} lines", misfits.len())
            },
            misfits.join("\n")
        ));
    }
    Ok(with_content(text, ladder, |_| true, &lines.join("\n")))
}

/// The cycle's ladder planned from the workspace at `root`: the cycle
/// title and the rung headings read from `TODO.md`, `commits` the
/// titles on the branch, and `zTOC.md`'s new text, `None` when the
/// ladder there is as made already.
#[derive(Debug)]
pub(crate) struct LadderPlan {
    pub ladder: Ladder,
    pub edit: Option<FileEdit>,
}

/// Plan the ladder, reading both files and writing neither.
pub(crate) fn plan_ladder(root: &Path, commits: &[String]) -> Result<LadderPlan, String> {
    let read = |name: &str| {
        let p = root.join(name);
        std::fs::read_to_string(&p).map_err(|e| format!("{}: {e}", p.display()))
    };
    let todo = read(RECORD)?;
    let ladder = ladder_of(&cycle_title(&todo)?, &rung_titles(&todo)?, commits)?;
    let old = read(LADDER_FILE)?;
    let text = written_ladder(&old, &ladder.lines)?;
    let edit = (text != old).then(|| FileEdit {
        path: root.join(LADDER_FILE),
        text,
    });
    Ok(LadderPlan { ladder, edit })
}

/// One file's edit, planned: its path and its new text.
#[derive(Debug)]
pub(crate) struct FileEdit {
    pub path: PathBuf,
    pub text: String,
}

/// What `cycle --open` writes, planned before anything is made.
#[derive(Debug, Default)]
pub(crate) struct OpenRecord {
    /// The files written, the record then the ladder.
    pub edits: Vec<FileEdit>,
    /// What the edits do, and what was left out and why, a line each.
    pub did: Vec<String>,
}

/// Plan the record of the cycle `title` in the workspace at `root`,
/// reading and checking both files, so a refusal comes before the
/// bookmark is made. A workspace missing either file is refused, naming
/// what a cycle needs, since without its record the later stages
/// refuse and the bookmark would be a branch and not a cycle.
pub(crate) fn plan_open(root: &Path, title: &str) -> Result<OpenRecord, String> {
    let mut plan = OpenRecord::default();
    let record = root.join(RECORD);
    let ladder = root.join(LADDER_FILE);
    let missing: Vec<&str> = [(RECORD, &record), (LADDER_FILE, &ladder)]
        .into_iter()
        .filter(|(_, p)| !p.is_file())
        .map(|(name, _)| name)
        .collect();
    if !missing.is_empty() {
        return Err(format!(
            "{} has no {}, and a cycle runs on its record: {RECORD} with `## In Progress` and \
             `## Closed`, and {LADDER_FILE} with `{LADDER}`. Add them, or --no-record makes the \
             bookmark alone, a branch that `cycle --commit` and `--close` will not take",
            root.display(),
            missing.join(" or ")
        ));
    }
    let read = |p: &Path| std::fs::read_to_string(p).map_err(|e| format!("{}: {e}", p.display()));
    let (text, did) = opened_record(&read(&record)?, title)?;
    plan.did = did;
    plan.edits.push(FileEdit { path: record, text });
    let text = opened_ladder(&read(&ladder)?, title)?;
    plan.did.push(format!(

//! The cycle-record's mechanical edits, as text: what `cycle --open`
//! writes into `TODO.md` and `zTOC.md`.
//!
//! - The record's shape is the agent-files', so the tool knows it
//!   without knowing the work: `TODO.md`'s `## In Progress`, `## Todo`,
//!   and `## Closed`, and `zTOC.md`'s `## Ladder`.
//! - Every function here takes a file's text and returns its new
//!   text, so a refusal comes before anything is written and a dry
//!   run is the same code.
//! - A heading inside a fenced code block is not one, as the closing's
//!   record move has it.

use std::path::{Path, PathBuf};

use crate::check::anchors::anchor_slug;
use crate::commit::{NONE_IN_PROGRESS, RECORD, section};

/// The ladder's file, beside the record.
pub(crate) const LADDER_FILE: &str = "zTOC.md";

/// The ladder's heading in [`LADDER_FILE`].
const LADDER: &str = "## Ladder";

/// What an item of the scaffold reads until it is written.
const TO_WRITE: &str = "_To write._";

/// The lines of `text` outside fenced code, each with its byte offset
/// and its text less the line ending.
fn prose_lines(text: &str) -> impl Iterator<Item = (usize, &str)> {
    let mut fenced = false;
    let mut at = 0;
    text.split_inclusive('\n').filter_map(move |line| {
        let start = at;
        at += line.len();
        let bare = line.trim_end_matches(['\n', '\r']);
        if bare.starts_with("```") {
            fenced = !fenced;
            return None;
        }
        (!fenced).then_some((start, bare))
    })
}

/// A section's body with its content replaced: the intro, everything
/// before the first line `starts` accepts, is kept, then `content`,
/// none when it is empty, and a blank line before the next heading
/// unless the file ends there.
fn with_content(
    text: &str,
    (start, end): (usize, usize),
    starts: impl Fn(&str) -> bool,
    content: &str,
) -> String {
    let body = &text[start..end];
    let from = prose_lines(body)
        .find(|(_, l)| starts(l))
        .map_or(body.len(), |(at, _)| at);
    let intro = body[..from].trim_end();
    let content = content.trim_end();
    let mut new = String::new();
    if !intro.trim().is_empty() {
        new.push_str(intro);
        new.push('\n');
    }
    if !content.is_empty() {
        new.push('\n');
        new.push_str(content);
        new.push('\n');
    }
    if end != text.len() {
        new.push('\n');
    }
    format!("{}{new}{}", &text[..start], &text[end..])
}

/// The `## Todo` entry titled `title` in `text`: its byte range, the
/// heading to the next entry or the section's end, and its text.
fn todo_entry(text: &str, title: &str) -> Option<((usize, usize), String)> {
    let (start, end) = section(text, "## Todo")?;
    let body = &text[start..end];
    let heading = format!("### {}", title.trim());
    let mut lines = prose_lines(body).skip_while(|(_, l)| l.trim_end() != heading);
    let (from, first) = lines.next()?;
    let to = lines
        .find(|(_, l)| l.starts_with("### "))
        .map_or(body.len(), |(at, _)| at);
    let entry = body[from + first.len()..to].trim().to_string();
    Some(((start + from, start + to), entry))
}

/// The `## In Progress` scaffold of the cycle `title`: the title, the
/// items, `problem` under Problem, and the opening and closing rung
/// subsections, in the specimen's shape.
fn scaffold(title: &str, problem: &str) -> String {
    let problem = if problem.is_empty() {
        TO_WRITE
    } else {
        problem
    };
    format!(
        "### {title}\n\n\
         #### Problem\n\n{problem}\n\n\
         #### Solution\n\n{TO_WRITE}\n\n\
         #### Acceptance check\n\n{TO_WRITE}\n\n\
         #### Deliberation\n\n_None._\n\n\
         #### Rungs\n\n\
         The rung subsections, in the ladder's order. The ladder itself is in `{LADDER_FILE} > \
         {LADDER}`.\n\n\
         ##### {title} opening\n\n\
         The cycle's first commit, carrying its plan: the bookmark, the last cycle's record \
         deleted, and the\nTodo entry moved into this block.\n\n\
         ##### {title} closing\n\n\
         Closing out the cycle.\n"
    )
}

/// `TODO.md`'s text with the cycle `title` opened, and what was done,
/// a line each: what `## Closed` holds is deleted, the `## Todo` entry
/// titled so is moved into an `## In Progress` scaffold, an empty one
/// when none matches. Refused when there is no `## In Progress` or a
/// cycle is in it.
pub(crate) fn opened_record(text: &str, title: &str) -> Result<(String, Vec<String>), String> {
    let title = title.trim();
    let entry = |l: &str| l.starts_with("### ");
    let content = |l: &str| entry(l) || l == NONE_IN_PROGRESS;
    let progress = section(text, "## In Progress")
        .ok_or_else(|| format!("{RECORD} has no `## In Progress` to open the cycle in"))?;
    if let Some((_, running)) = prose_lines(&text[progress.0..progress.1]).find(|(_, l)| entry(l)) {
        return Err(format!(
            "{RECORD} has a cycle in progress, '{}': it closes first",
            running.trim_start_matches("### ")
        ));
    }
    let mut did = Vec::new();
    let found = todo_entry(text, title);
    let problem = match &found {
        Some((_, entry)) => {
            did.push(format!(
                "move the `## Todo` entry '{title}' into `## In Progress`"
            ));
            entry.as_str()
        }
        None => {
            did.push(format!(
                "no `## Todo` entry is titled '{title}', so `## In Progress` gets an empty scaffold"
            ));
            ""
        }
    };
    // The edits, each a range and the text that replaces it, applied
    // last first, so an earlier one's offsets still hold.
    let mut edits: Vec<((usize, usize), String)> = Vec::new();
    let opened = with_content(text, progress, content, &scaffold(title, problem));
    edits.push((
        progress,
        opened[progress.0..opened.len() - (text.len() - progress.1)].to_string(),
    ));
    if let Some((range, _)) = found {
        edits.push((range, String::new()));
    }
    match section(text, "## Closed") {
        Some(closed) => {
            let emptied = with_content(text, closed, entry, "");
            let body = emptied[closed.0..emptied.len() - (text.len() - closed.1)].to_string();
            if body != text[closed.0..closed.1] {
                did.insert(0, "delete what `## Closed` holds".to_string());
            }
            edits.push((closed, body));
        }
        None => did.insert(0, "no `## Closed`, so nothing is deleted".to_string()),
    }
    edits.sort_by_key(|((start, _), _)| std::cmp::Reverse(*start));
    let mut new = text.to_string();
    for ((start, end), with) in edits {
        new.replace_range(start..end, &with);
    }
    Ok((new, did))
}

/// The items of the cycle in progress in `TODO.md`'s `text` still
/// reading the scaffold's placeholder: Problem, Solution, and
/// Acceptance check, in that order.
pub(crate) fn unwritten_items(text: &str) -> Vec<&'static str> {
    let Some((start, end)) = section(text, "## In Progress") else {
        return Vec::new();
    };
    let body = &text[start..end];
    let lines: Vec<(usize, &str)> = prose_lines(body).collect();
    ["Problem", "Solution", "Acceptance check"]
        .into_iter()
        .filter(|item| {
            let heading = format!("#### {item}");
            let Some(i) = lines.iter().position(|(_, l)| l.trim_end() == heading) else {
                return false;
            };
            let text: Vec<&str> = lines[i + 1..]
                .iter()
                .take_while(|(_, l)| !l.starts_with('#'))
                .map(|(_, l)| l.trim())
                .filter(|l| !l.is_empty())
                .collect();
            text == [TO_WRITE]
        })
        .collect()
}

/// `TODO.md`'s text with the `#### Rungs` item of the cycle `## Closed`
/// holds removed, its heading to the next heading of its level or
/// above, for a single-step cycle, whose one commit has no rungs.
pub(crate) fn without_closed_rungs(text: &str) -> String {
    let Some((start, end)) = section(text, "## Closed") else {
        return text.to_string();
    };
    let body = &text[start..end];
    let mut lines = prose_lines(body).skip_while(|(_, l)| l.trim_end() != "#### Rungs");
    let Some((from, _)) = lines.next() else {
        return text.to_string();
    };
    let above = |l: &str| {
        ["# ", "## ", "### ", "#### "]
            .iter()
            .any(|h| l.starts_with(h))
    };
    let to = lines
        .find(|(_, l)| above(l))
        .map_or(body.len(), |(at, _)| at);
    let kept = format!("{}{}", body[..from].trim_end(), "\n\n");
    let tail = &body[to..];
    let new_body = if tail.is_empty() && end == text.len() {
        format!("{}\n", kept.trim_end())
    } else if tail.is_empty() {
        kept
    } else {
        format!("{kept}{tail}")
    };
    format!("{}{new_body}{}", &text[..start], &text[end..])
}

/// A ladder's line for a rung not yet started: the title linked to
/// its subsection in the record.
fn rung_link(title: &str) -> String {
    format!("[{title}]({RECORD}#{})", anchor_slug(title))
}

/// `zTOC.md`'s text with the ladder of a cycle just opened in place of
/// the last cycle's: the opening and the closing, neither marked. Refused
/// when there is no `## Ladder`.
pub(crate) fn opened_ladder(text: &str, title: &str) -> Result<String, String> {
    let title = title.trim();
    let rungs = [format!("{title} opening"), format!("{title} closing")];
    // A new cycle replaces the last one's ladder whatever its lines
    // were, so the grammar is not asked of them.
    let ladder = section(text, LADDER)
        .ok_or_else(|| format!("{LADDER_FILE} has no `{LADDER}` to write the cycle's ladder in"))?;
    let made = ladder_of(title, &rungs, &[])?;
    Ok(with_content(text, ladder, |_| true, &made.lines.join("\n")))
}

/// The title of the cycle in progress in `TODO.md`'s `text`, its
/// `### ` heading under `## In Progress`. Refused when there is none.
pub(crate) fn cycle_title(text: &str) -> Result<String, String> {
    let (start, end) = section(text, "## In Progress")
        .ok_or_else(|| format!("{RECORD} has no `## In Progress`"))?;
    prose_lines(&text[start..end])
        .find_map(|(_, l)| l.strip_prefix("### "))
        .map(|t| t.trim().to_string())
        .ok_or_else(|| format!("{RECORD} has no cycle in progress: `cycle --open` opens one"))
}

/// The title of the cycle `## Closed` holds in `TODO.md`'s `text`, the
/// last one closed, `None` when it holds none.
pub(crate) fn closed_title(text: &str) -> Option<String> {
    let (start, end) = section(text, "## Closed")?;
    prose_lines(&text[start..end])
        .find_map(|(_, l)| l.strip_prefix("### "))
        .map(|t| t.trim().to_string())
}

/// The rung titles of the cycle in progress, in their order: the
/// `##### ` headings under its `#### Rungs`, to the next heading of
/// that level or above. Refused when there is no `#### Rungs` or it
/// holds no rung.
pub(crate) fn rung_titles(text: &str) -> Result<Vec<String>, String> {
    let (start, end) = section(text, "## In Progress")
        .ok_or_else(|| format!("{RECORD} has no `## In Progress`"))?;
    let mut lines =
        prose_lines(&text[start..end]).skip_while(|(_, l)| l.trim_end() != "#### Rungs");
    if lines.next().is_none() {
        return Err(format!(
            "{RECORD}'s cycle has no `#### Rungs` heading to read its rungs from"
        ));
    }
    let above = |l: &str| {
        ["# ", "## ", "### ", "#### "]
            .iter()
            .any(|h| l.starts_with(h))
    };
    let rungs: Vec<String> = lines
        .take_while(|(_, l)| !above(l))
        .filter_map(|(_, l)| l.strip_prefix("##### "))
        .map(|t| t.trim().to_string())
        .collect();
    if rungs.is_empty() {
        return Err(format!(
            "{RECORD}'s `#### Rungs` holds no rung, a `##### <title>` heading each"
        ));
    }
    Ok(rungs)
}

/// A ladder made: its lines, and what a reader should know that the
/// lines do not refuse, a line each.
#[derive(Debug, PartialEq, Eq)]
pub(crate) struct Ladder {
    pub lines: Vec<String>,
    pub findings: Vec<String>,
}

/// The ladder of the cycle `cycle`, a line per rung in `rungs`' order,
/// `commits` being the titles of the commits on its branch. A rung is
/// `(done)`, numbered by its position, when a commit has its title, and
/// every other rung is its link alone, so the first unmarked rung is
/// the next and no line claims work not yet begun. A single-step cycle,
/// its one commit under the bare cycle title, is one unlinked rung.
///
/// Refused: a title written twice, a ladder not opened by the cycle
/// title plus " opening" or not closed by it plus " closing", and a
/// commit whose title is no rung's, each naming what it found. A done
/// rung below the first rung not done is a finding, the ladder still
/// made.
pub(crate) fn ladder_of(
    cycle: &str,
    rungs: &[String],
    commits: &[String],
) -> Result<Ladder, String> {
    for (i, r) in rungs.iter().enumerate() {
        if rungs[..i].contains(r) {
            return Err(format!(
                "the rung '{r}' is written twice under `#### Rungs`"
            ));
        }
    }
    let (opening, closing) = (format!("{cycle} opening"), format!("{cycle} closing"));
    if rungs.first() != Some(&opening) {
        return Err(format!(
            "the first rung under `#### Rungs` is not the cycle's opening, '{opening}'"
        ));
    }
    if rungs.len() < 2 || rungs.last() != Some(&closing) {
        return Err(format!(
            "the last rung under `#### Rungs` is not the cycle's closing, '{closing}'"
        ));
    }
    let strays: Vec<&String> = commits
        .iter()
        .filter(|c| c.as_str() != cycle && !rungs.contains(c))
        .collect();
    if !strays.is_empty() {
        return Err(format!(
            "{} on the cycle's branch match no rung under `#### Rungs`, and every commit of a \
             cycle is a rung's: {}",
            if strays.len() == 1 {
                "a commit's title".to_string()
            } else {
                format!("{} commits' titles", strays.len())
            },
            strays
                .iter()
                .map(|s| format!("'{s}'"))
                .collect::<Vec<_>>()
                .join(", ")
        ));
    }
    if commits.iter().any(|c| c == cycle) {
        if commits.len() > 1 {
            return Err(format!(
                "the branch has a commit titled '{cycle}', a single-step cycle's one commit, \
                 beside {} more",
                commits.len() - 1
            ));
        }
        return Ok(Ladder {
            lines: vec![format!("- 0 (done) {cycle}")],
            findings: Vec::new(),
        });
    }
    let next = rungs.iter().position(|r| !commits.contains(r));
    let mut findings = Vec::new();
    let lines = rungs
        .iter()
        .enumerate()
        .map(|(i, r)| {
            let link = rung_link(r);
            if commits.contains(r) {
                if let Some(n) = next
                    && n < i
                {
                    findings.push(format!(
                        "the rung '{r}' is done and is below '{}', a rung not done",
                        rungs[n]
                    ));
                }
                format!("- {i} (done) {link}")
            } else {
                format!("- {link}")
            }
        })
        .collect();
    Ok(Ladder { lines, findings })
}

/// A ladder line with its link reduced to the title it shows,
/// `- 1 (done) [feat: x](TODO.md#feat-x)` to `- 1 (done) feat: x`,
/// for a terminal, where the link cannot be followed.
pub(crate) fn unlinked(line: &str) -> String {
    let Some(open) = line.find('[') else {
        return line.to_string();
    };
    let Some(close) = line[open..].find("](").map(|i| open + i) else {
        return line.to_string();
    };
    if !line.ends_with(')') {
        return line.to_string();
    }
    format!("{}{}", &line[..open], &line[open + 1..close])
}

/// Whether `line`, a left-margin bullet, is a rung by the ladder's
/// grammar: `- `, then optionally a number and `(done)`, then the
/// title, linked to its slug in the record or, for a single-step cycle,
/// bare. A number and `(current)`, which a `vc-x1` before 0.85.26 wrote
/// on the next rung, is read too, so a ladder from mid-cycle at an
/// upgrade is still a ladder and is rewritten without it.
fn is_rung(line: &str) -> bool {
    let Some(rest) = line.strip_prefix("- ") else {
        return false;
    };
    let digits = rest.len() - rest.trim_start_matches(|c: char| c.is_ascii_digit()).len();
    let rest = match digits {
        0 => rest,
        _ => {
            let after = &rest[digits..];
            match after
                .strip_prefix(" (current) ")
                .or_else(|| after.strip_prefix(" (done) "))
            {
                Some(title) => title,
                None => return false,
            }
        }
    };
    match rest.strip_prefix('[') {
        Some(linked) => linked
            .split_once(&format!("]({RECORD}#"))
            .and_then(|(title, slug)| Some((title, slug.strip_suffix(')')?)))
            .is_some_and(|(title, slug)| !title.is_empty() && slug == anchor_slug(title)),
        None => !rest.trim().is_empty() && rest == rest.trim() && !rest.contains("]("),
    }
}

/// `zTOC.md`'s text with `lines` as its ladder. Refused, with nothing
/// edited, when there is no `## Ladder`, or when a line of the ladder
/// there does not fit the grammar, each such line named: a rung is a
/// left-margin bullet, and anything else but a blank line and the
/// skeleton's `_None._` is a line the rewrite would lose.
pub(crate) fn written_ladder(text: &str, lines: &[String]) -> Result<String, String> {
    let ladder = section(text, LADDER)
        .ok_or_else(|| format!("{LADDER_FILE} has no `{LADDER}` to write the cycle's ladder in"))?;
    let misfits: Vec<String> = text[ladder.0..ladder.1]
        .lines()
        .filter(|l| !l.trim().is_empty() && l.trim() != "_None._" && !is_rung(l))
        .map(|l| format!("  {l}"))
        .collect();
    if !misfits.is_empty() {
        return Err(format!(
            "{LADDER_FILE}'s `{LADDER}` holds {} that a rung's grammar does not fit, `- [N \
             (done)] [<title>]({RECORD}#<slug>)`, so nothing is edited:\n{}",
            if misfits.len() == 1 {
                "a line".to_string()
            } else {
                format!("{} lines", misfits.len())
            },
            misfits.join("\n")
        ));
    }
    Ok(with_content(text, ladder, |_| true, &lines.join("\n")))
}

/// The cycle's ladder planned from the workspace at `root`: the cycle
/// title and the rung headings read from `TODO.md`, `commits` the
/// titles on the branch, and `zTOC.md`'s new text, `None` when the
/// ladder there is as made already.
#[derive(Debug)]
pub(crate) struct LadderPlan {
    pub ladder: Ladder,
    pub edit: Option<FileEdit>,
}

/// Plan the ladder, reading both files and writing neither.
pub(crate) fn plan_ladder(root: &Path, commits: &[String]) -> Result<LadderPlan, String> {
    let read = |name: &str| {
        let p = root.join(name);
        std::fs::read_to_string(&p).map_err(|e| format!("{}: {e}", p.display()))
    };
    let todo = read(RECORD)?;
    let ladder = ladder_of(&cycle_title(&todo)?, &rung_titles(&todo)?, commits)?;
    let old = read(LADDER_FILE)?;
    let text = written_ladder(&old, &ladder.lines)?;
    let edit = (text != old).then(|| FileEdit {
        path: root.join(LADDER_FILE),
        text,
    });
    Ok(LadderPlan { ladder, edit })
}

/// One file's edit, planned: its path and its new text.
#[derive(Debug)]
pub(crate) struct FileEdit {
    pub path: PathBuf,
    pub text: String,
}

/// What `cycle --open` writes, planned before anything is made.
#[derive(Debug, Default)]
pub(crate) struct OpenRecord {
    /// The files written, the record then the ladder.
    pub edits: Vec<FileEdit>,
    /// What the edits do, and what was left out and why, a line each.
    pub did: Vec<String>,
}

