        assert!(err.contains("no `[version] bump`"), "{err}");
        write("bump = \"cargo xtask bump\"\n");
        let err = bump_words(&dir, "1.2.3").unwrap_err().to_string();
        assert!(err.contains("no `{ver}`"), "{err}");
    }
}

